-- Aprenda se Divertindo · 78 · Baralho de cartões · trilha Tribunais (500 cartões)
-- Rode depois do 77-cartoes-enem.sql. Cole TUDO no SQL Editor e clique em Run. Pode rodar de novo sem problema.
--
-- Matérias que ainda não tinham cartões: Direito Civil, Processo Civil, Arquivologia, Dir. Previdenciário,
-- Dir. Tributário e Adm. Pública. As demais matérias da trilha (Português, Constitucional, Administrativo, Penal,
-- Processo Penal, Informática, Raciocínio Lógico...) já usam os 1.000 cartões da Policial, que valem por matéria.
-- Previdenciário, Tributário e Adm. Pública também passam a valer na trilha Fiscal.
-- Cartões numerados de 2.000.001.501 a 2.000.002.000. O jogo baixa os novos cartões sozinho.

insert into public.cartoes (id, trilha, materia, assunto, tipo, frente, verso, explicacao)
select id, trilha, materia, assunto, tipo, frente, verso, explicacao
from jsonb_to_recordset($c$[{"id": 2000001501, "trilha": "tribunais", "materia": "civ", "assunto": "LINDB", "tipo": "pergunta", "frente": "Em regra, quando uma lei começa a vigorar no Brasil se não disser o prazo?", "verso": "45 dias depois de oficialmente publicada.", "explicacao": "LINDB, art. 1º. No exterior, 3 meses."}, {"id": 2000001502, "trilha": "tribunais", "materia": "civ", "assunto": "LINDB", "tipo": "pergunta", "frente": "A lei revogada volta a valer se a lei revogadora perder a vigência?", "verso": "Não, salvo disposição expressa. O Brasil não admite repristinação automática.", "explicacao": "LINDB, art. 2º, § 3º."}, {"id": 2000001503, "trilha": "tribunais", "materia": "civ", "assunto": "LINDB", "tipo": "pergunta", "frente": "Alguém pode deixar de cumprir a lei alegando que não a conhece?", "verso": "Não.", "explicacao": "LINDB, art. 3º."}, {"id": 2000001504, "trilha": "tribunais", "materia": "civ", "assunto": "LINDB", "tipo": "pergunta", "frente": "O que o juiz faz quando a lei for omissa?", "verso": "Decide de acordo com a analogia, os costumes e os princípios gerais de direito.", "explicacao": "LINDB, art. 4º."}, {"id": 2000001505, "trilha": "tribunais", "materia": "civ", "assunto": "LINDB", "tipo": "pares", "frente": "Ato jurídico perfeito x direito adquirido x coisa julgada.", "verso": "Ato jurídico perfeito: já consumado segundo a lei do seu tempo. Direito adquirido: já incorporado ao patrimônio, ainda que não exercido. Coisa julgada: decisão de que não cabe mais recurso.", "explicacao": "LINDB, art. 6º. A lei nova não os prejudica."}, {"id": 2000001506, "trilha": "tribunais", "materia": "civ", "assunto": "Pessoa natural", "tipo": "pergunta", "frente": "Quando começa a personalidade civil da pessoa?", "verso": "Do nascimento com vida; a lei põe a salvo, desde a concepção, os direitos do nascituro.", "explicacao": "CC, art. 2º."}, {"id": 2000001507, "trilha": "tribunais", "materia": "civ", "assunto": "Pessoa natural", "tipo": "pergunta", "frente": "Quem é absolutamente incapaz no Código Civil atual?", "verso": "Apenas os menores de 16 anos.", "explicacao": "CC, art. 3º, com redação do Estatuto da Pessoa com Deficiência."}, {"id": 2000001508, "trilha": "tribunais", "materia": "civ", "assunto": "Pessoa natural", "tipo": "pergunta", "frente": "Quem é relativamente incapaz?", "verso": "Maiores de 16 e menores de 18; ébrios habituais e viciados em tóxicos; os que, por causa transitória ou permanente, não puderem exprimir vontade; e os pródigos.", "explicacao": "CC, art. 4º."}, {"id": 2000001509, "trilha": "tribunais", "materia": "civ", "assunto": "Pessoa natural", "tipo": "pergunta", "frente": "Em que hipóteses cessa a incapacidade do menor antes dos 18 anos?", "verso": "Emancipação pelos pais (a partir de 16), por sentença, casamento, emprego público efetivo, colação de grau em curso superior, estabelecimento civil ou comercial ou emprego que dê economia própria (a partir de 16).", "explicacao": "CC, art. 5º, parágrafo único."}, {"id": 2000001510, "trilha": "tribunais", "materia": "civ", "assunto": "Pessoa natural", "tipo": "pergunta", "frente": "A emancipação voluntária pelos pais exige sentença judicial?", "verso": "Não. É feita por instrumento público, sem homologação judicial.", "explicacao": "CC, art. 5º, parágrafo único, I."}, {"id": 2000001511, "trilha": "tribunais", "materia": "civ", "assunto": "Pessoa natural", "tipo": "pergunta", "frente": "O que é comoriência?", "verso": "Quando duas ou mais pessoas morrem na mesma ocasião sem se saber quem morreu primeiro; presume-se que morreram ao mesmo tempo.", "explicacao": "CC, art. 8º. Uma não herda da outra."}, {"id": 2000001512, "trilha": "tribunais", "materia": "civ", "assunto": "Pessoa natural", "tipo": "pergunta", "frente": "Em que casos se declara morte presumida sem decretação de ausência?", "verso": "Se for extremamente provável a morte de quem estava em perigo de vida, ou se alguém desaparecido em campanha ou feito prisioneiro não for encontrado até 2 anos após o fim da guerra.", "explicacao": "CC, art. 7º."}, {"id": 2000001513, "trilha": "tribunais", "materia": "civ", "assunto": "Ausência", "tipo": "pergunta", "frente": "Quais as três fases da ausência?", "verso": "Curadoria dos bens do ausente, sucessão provisória e sucessão definitiva.", "explicacao": "CC, arts. 22 a 39."}, {"id": 2000001514, "trilha": "tribunais", "materia": "civ", "assunto": "Direitos da personalidade", "tipo": "pergunta", "frente": "Quais as características dos direitos da personalidade?", "verso": "São intransmissíveis e irrenunciáveis, e seu exercício não pode sofrer limitação voluntária, salvo nos casos previstos em lei.", "explicacao": "CC, art. 11."}, {"id": 2000001515, "trilha": "tribunais", "materia": "civ", "assunto": "Direitos da personalidade", "tipo": "pergunta", "frente": "É válida a disposição gratuita do próprio corpo para depois da morte?", "verso": "Sim, com objetivo científico ou altruístico, e pode ser revogada a qualquer tempo.", "explicacao": "CC, art. 14."}, {"id": 2000001516, "trilha": "tribunais", "materia": "civ", "assunto": "Pessoa jurídica", "tipo": "pergunta", "frente": "Quais são as pessoas jurídicas de direito privado?", "verso": "Associações, sociedades, fundações, organizações religiosas e partidos políticos.", "explicacao": "CC, art. 44."}, {"id": 2000001517, "trilha": "tribunais", "materia": "civ", "assunto": "Pessoa jurídica", "tipo": "pares", "frente": "Associação x fundação.", "verso": "Associação: união de pessoas para fins não econômicos. Fundação: patrimônio destinado a um fim (religioso, cultural, assistencial etc.), por escritura pública ou testamento.", "explicacao": "CC, arts. 53 e 62."}, {"id": 2000001518, "trilha": "tribunais", "materia": "civ", "assunto": "Pessoa jurídica", "tipo": "pergunta", "frente": "Quando ocorre a desconsideração da personalidade jurídica?", "verso": "Em caso de abuso da personalidade, caracterizado por desvio de finalidade ou confusão patrimonial.", "explicacao": "CC, art. 50 (teoria maior)."}, {"id": 2000001519, "trilha": "tribunais", "materia": "civ", "assunto": "Pessoa jurídica", "tipo": "pergunta", "frente": "Quem fiscaliza as fundações?", "verso": "O Ministério Público do estado onde estiverem situadas.", "explicacao": "CC, art. 66."}, {"id": 2000001520, "trilha": "tribunais", "materia": "civ", "assunto": "Domicílio", "tipo": "pergunta", "frente": "Qual o domicílio da pessoa natural?", "verso": "O lugar onde ela estabelece sua residência com ânimo definitivo.", "explicacao": "CC, art. 70. Se tiver várias residências, qualquer delas."}, {"id": 2000001521, "trilha": "tribunais", "materia": "civ", "assunto": "Domicílio", "tipo": "pergunta", "frente": "Qual o domicílio necessário do servidor público e do preso?", "verso": "Servidor: o lugar onde exerce permanentemente suas funções. Preso: o lugar onde cumpre a sentença.", "explicacao": "CC, art. 76."}, {"id": 2000001522, "trilha": "tribunais", "materia": "civ", "assunto": "Bens", "tipo": "pares", "frente": "Bens fungíveis x consumíveis.", "verso": "Fungíveis: móveis que podem ser substituídos por outros da mesma espécie, qualidade e quantidade (dinheiro). Consumíveis: cujo uso importa destruição imediata (alimentos).", "explicacao": "CC, arts. 85 e 86."}, {"id": 2000001523, "trilha": "tribunais", "materia": "civ", "assunto": "Bens", "tipo": "pares", "frente": "Benfeitorias necessárias x úteis x voluptuárias.", "verso": "Necessárias: conservam o bem ou evitam que se deteriore. Úteis: aumentam ou facilitam o uso. Voluptuárias: de mero deleite ou recreio.", "explicacao": "CC, art. 96."}, {"id": 2000001524, "trilha": "tribunais", "materia": "civ", "assunto": "Bens", "tipo": "pares", "frente": "Frutos x produtos.", "verso": "Frutos: utilidades que se renovam periodicamente sem diminuir o bem (aluguel, colheita). Produtos: utilidades cuja retirada diminui o bem (minério de uma jazida).", "explicacao": ""}, {"id": 2000001525, "trilha": "tribunais", "materia": "civ", "assunto": "Bens", "tipo": "pergunta", "frente": "Os bens públicos podem ser adquiridos por usucapião?", "verso": "Não.", "explicacao": "CC, art. 102; CF, arts. 183, § 3º, e 191, parágrafo único."}, {"id": 2000001526, "trilha": "tribunais", "materia": "civ", "assunto": "Bens", "tipo": "pares", "frente": "Bens de uso comum x de uso especial x dominicais.", "verso": "Uso comum: rios, mares, estradas, ruas e praças. Uso especial: edifícios destinados a serviço público. Dominicais: patrimônio disponível das pessoas de direito público.", "explicacao": "CC, art. 99. Só os dominicais podem ser alienados, observada a lei."}, {"id": 2000001527, "trilha": "tribunais", "materia": "civ", "assunto": "Negócio jurídico", "tipo": "pergunta", "frente": "Quais os requisitos de validade do negócio jurídico?", "verso": "Agente capaz, objeto lícito, possível, determinado ou determinável e forma prescrita ou não proibida em lei.", "explicacao": "CC, art. 104."}, {"id": 2000001528, "trilha": "tribunais", "materia": "civ", "assunto": "Negócio jurídico", "tipo": "pares", "frente": "Erro x dolo.", "verso": "Erro: a pessoa se engana sozinha sobre elemento essencial. Dolo: ela é induzida ao engano pela outra parte ou por terceiro.", "explicacao": "Ambos tornam o negócio anulável."}, {"id": 2000001529, "trilha": "tribunais", "materia": "civ", "assunto": "Negócio jurídico", "tipo": "pares", "frente": "Estado de perigo x lesão.", "verso": "Estado de perigo: assume obrigação excessivamente onerosa para salvar a si ou a pessoa da família de grave dano conhecido pela outra parte. Lesão: por premente necessidade ou inexperiência, obriga-se a prestação manifestamente desproporcional.", "explicacao": "CC, arts. 156 e 157."}, {"id": 2000001530, "trilha": "tribunais", "materia": "civ", "assunto": "Negócio jurídico", "tipo": "pergunta", "frente": "Qual a consequência da simulação?", "verso": "O negócio é nulo, mas subsiste o que se dissimulou, se for válido na substância e na forma.", "explicacao": "CC, art. 167."}, {"id": 2000001531, "trilha": "tribunais", "materia": "civ", "assunto": "Negócio jurídico", "tipo": "pares", "frente": "Nulidade x anulabilidade.", "verso": "Nulo: não convalesce com o tempo, pode ser alegado por qualquer interessado ou pelo MP e declarado de ofício. Anulável: pode ser confirmado, só os interessados alegam e há prazo decadencial.", "explicacao": "CC, arts. 168 a 172."}, {"id": 2000001532, "trilha": "tribunais", "materia": "civ", "assunto": "Negócio jurídico", "tipo": "pergunta", "frente": "Qual o prazo para pleitear a anulação por erro, dolo, coação, fraude contra credores, estado de perigo ou lesão?", "verso": "4 anos (decadencial).", "explicacao": "CC, art. 178. Na coação, conta do dia em que ela cessar."}, {"id": 2000001533, "trilha": "tribunais", "materia": "civ", "assunto": "Negócio jurídico", "tipo": "pergunta", "frente": "O que é fraude contra credores?", "verso": "Atos do devedor insolvente (ou levado à insolvência) que reduzem seu patrimônio e prejudicam credores, como doação de bens.", "explicacao": "Anulável por ação pauliana. CC, art. 158."}, {"id": 2000001534, "trilha": "tribunais", "materia": "civ", "assunto": "Negócio jurídico", "tipo": "pares", "frente": "Condição x termo x encargo.", "verso": "Condição: evento futuro e incerto. Termo: evento futuro e certo. Encargo (modo): ônus imposto em liberalidade.", "explicacao": "CC, arts. 121, 131 e 136."}, {"id": 2000001535, "trilha": "tribunais", "materia": "civ", "assunto": "Negócio jurídico", "tipo": "pergunta", "frente": "Qual a forma exigida para negócios sobre imóveis de valor superior a 30 salários mínimos?", "verso": "Escritura pública.", "explicacao": "CC, art. 108."}, {"id": 2000001536, "trilha": "tribunais", "materia": "civ", "assunto": "Prescrição e decadência", "tipo": "pares", "frente": "Prescrição x decadência.", "verso": "Prescrição: perda da pretensão (exigir em juízo), atinge direitos prestacionais; admite suspensão e interrupção. Decadência: perda do próprio direito potestativo; em regra não se suspende nem se interrompe.", "explicacao": "CC, arts. 189 e 207."}, {"id": 2000001537, "trilha": "tribunais", "materia": "civ", "assunto": "Prescrição e decadência", "tipo": "pergunta", "frente": "Qual o prazo geral de prescrição no Código Civil?", "verso": "10 anos, quando a lei não fixar prazo menor.", "explicacao": "CC, art. 205."}, {"id": 2000001538, "trilha": "tribunais", "materia": "civ", "assunto": "Prescrição e decadência", "tipo": "pergunta", "frente": "Qual o prazo de prescrição da pretensão de reparação civil?", "verso": "3 anos.", "explicacao": "CC, art. 206, § 3º, V."}, {"id": 2000001539, "trilha": "tribunais", "materia": "civ", "assunto": "Prescrição e decadência", "tipo": "pergunta", "frente": "Quantas vezes a prescrição pode ser interrompida?", "verso": "Uma única vez.", "explicacao": "CC, art. 202."}, {"id": 2000001540, "trilha": "tribunais", "materia": "civ", "assunto": "Prescrição e decadência", "tipo": "pergunta", "frente": "Corre prescrição contra absolutamente incapazes?", "verso": "Não.", "explicacao": "CC, art. 198, I."}, {"id": 2000001541, "trilha": "tribunais", "materia": "civ", "assunto": "Prescrição e decadência", "tipo": "pergunta", "frente": "Corre prescrição entre cônjuges na constância da sociedade conjugal?", "verso": "Não.", "explicacao": "CC, art. 197, I."}, {"id": 2000001542, "trilha": "tribunais", "materia": "civ", "assunto": "Prescrição e decadência", "tipo": "pergunta", "frente": "O juiz pode reconhecer a prescrição de ofício?", "verso": "Sim.", "explicacao": "CPC, art. 487, parágrafo único, e art. 332, § 1º."}, {"id": 2000001543, "trilha": "tribunais", "materia": "civ", "assunto": "Prescrição e decadência", "tipo": "pergunta", "frente": "A renúncia à prescrição pode ser feita antes de ela se consumar?", "verso": "Não. Só depois de consumada e sem prejuízo de terceiros.", "explicacao": "CC, art. 191."}, {"id": 2000001544, "trilha": "tribunais", "materia": "civ", "assunto": "Obrigações", "tipo": "pares", "frente": "Obrigação de dar x fazer x não fazer.", "verso": "Dar: entregar ou restituir coisa. Fazer: prestar um ato ou serviço. Não fazer: abster-se de um ato.", "explicacao": ""}, {"id": 2000001545, "trilha": "tribunais", "materia": "civ", "assunto": "Obrigações", "tipo": "pares", "frente": "Solidariedade ativa x passiva.", "verso": "Ativa: qualquer credor pode exigir a dívida toda. Passiva: o credor pode exigir a dívida toda de qualquer devedor.", "explicacao": "A solidariedade não se presume: resulta da lei ou da vontade. CC, art. 265."}, {"id": 2000001546, "trilha": "tribunais", "materia": "civ", "assunto": "Obrigações", "tipo": "pergunta", "frente": "Qual a regra sobre o lugar do pagamento?", "verso": "Em regra, no domicílio do devedor (dívida quesível), salvo convenção ou lei em contrário.", "explicacao": "CC, art. 327."}, {"id": 2000001547, "trilha": "tribunais", "materia": "civ", "assunto": "Obrigações", "tipo": "pergunta", "frente": "O que é pagamento em consignação?", "verso": "Depósito judicial ou em banco da coisa ou quantia devida, quando o credor se recusa a receber ou há dúvida sobre quem deve receber.", "explicacao": "CC, arts. 334 e 335."}, {"id": 2000001548, "trilha": "tribunais", "materia": "civ", "assunto": "Obrigações", "tipo": "pares", "frente": "Novação x compensação x confusão.", "verso": "Novação: nova obrigação extingue a anterior. Compensação: duas pessoas credoras e devedoras uma da outra. Confusão: credor e devedor passam a ser a mesma pessoa.", "explicacao": "Formas de extinção das obrigações."}, {"id": 2000001549, "trilha": "tribunais", "materia": "civ", "assunto": "Obrigações", "tipo": "pares", "frente": "Cessão de crédito x assunção de dívida.", "verso": "Cessão de crédito: o credor transfere o crédito; basta notificar o devedor. Assunção de dívida: terceiro assume a dívida; exige consentimento expresso do credor.", "explicacao": "CC, arts. 290 e 299."}, {"id": 2000001550, "trilha": "tribunais", "materia": "civ", "assunto": "Obrigações", "tipo": "pergunta", "frente": "Qual o limite da cláusula penal?", "verso": "Não pode exceder o valor da obrigação principal.", "explicacao": "CC, art. 412."}, {"id": 2000001551, "trilha": "tribunais", "materia": "civ", "assunto": "Obrigações", "tipo": "pergunta", "frente": "Quando se considera o devedor em mora numa obrigação positiva, líquida e com termo?", "verso": "No próprio vencimento, independentemente de interpelação (o dia interpela pelo homem).", "explicacao": "CC, art. 397."}, {"id": 2000001552, "trilha": "tribunais", "materia": "civ", "assunto": "Obrigações", "tipo": "pares", "frente": "Arras confirmatórias x penitenciais.", "verso": "Confirmatórias: confirmam o contrato e não dão direito de arrependimento. Penitenciais: há direito de arrependimento; quem deu perde as arras, quem recebeu devolve em dobro.", "explicacao": "CC, arts. 417 a 420."}, {"id": 2000001553, "trilha": "tribunais", "materia": "civ", "assunto": "Contratos", "tipo": "pergunta", "frente": "O que é a função social do contrato?", "verso": "A liberdade contratual é exercida nos limites da função social do contrato.", "explicacao": "CC, art. 421."}, {"id": 2000001554, "trilha": "tribunais", "materia": "civ", "assunto": "Contratos", "tipo": "pergunta", "frente": "O que exige a boa-fé objetiva nos contratos?", "verso": "Que as partes ajam com lealdade, probidade e cooperação na conclusão e na execução do contrato.", "explicacao": "CC, art. 422."}, {"id": 2000001555, "trilha": "tribunais", "materia": "civ", "assunto": "Contratos", "tipo": "pergunta", "frente": "Como se interpretam cláusulas ambíguas num contrato de adesão?", "verso": "Da maneira mais favorável ao aderente.", "explicacao": "CC, art. 423."}, {"id": 2000001556, "trilha": "tribunais", "materia": "civ", "assunto": "Contratos", "tipo": "pergunta", "frente": "O que é exceção do contrato não cumprido?", "verso": "Nos contratos bilaterais, nenhuma parte pode exigir a prestação da outra antes de cumprir a sua.", "explicacao": "CC, art. 476."}, {"id": 2000001557, "trilha": "tribunais", "materia": "civ", "assunto": "Contratos", "tipo": "pergunta", "frente": "O que é a resolução por onerosidade excessiva?", "verso": "Nos contratos de execução continuada, se a prestação ficar excessivamente onerosa por acontecimentos extraordinários e imprevisíveis, o devedor pode pedir a resolução.", "explicacao": "CC, art. 478 (teoria da imprevisão)."}, {"id": 2000001558, "trilha": "tribunais", "materia": "civ", "assunto": "Contratos", "tipo": "pergunta", "frente": "O que são vícios redibitórios?", "verso": "Defeitos ocultos da coisa recebida em contrato comutativo que a tornam imprópria ao uso ou lhe diminuem o valor.", "explicacao": "CC, art. 441."}, {"id": 2000001559, "trilha": "tribunais", "materia": "civ", "assunto": "Contratos", "tipo": "pergunta", "frente": "Qual o prazo para reclamar de vício redibitório em bem móvel e imóvel?", "verso": "30 dias para móvel e 1 ano para imóvel, contados da entrega efetiva.", "explicacao": "CC, art. 445."}, {"id": 2000001560, "trilha": "tribunais", "materia": "civ", "assunto": "Contratos", "tipo": "pergunta", "frente": "O que é evicção?", "verso": "Perda da coisa adquirida por decisão judicial ou administrativa que a atribui a terceiro com direito anterior.", "explicacao": "CC, art. 447."}, {"id": 2000001561, "trilha": "tribunais", "materia": "civ", "assunto": "Contratos", "tipo": "pergunta", "frente": "A venda de ascendente a descendente é válida?", "verso": "É anulável, salvo se os outros descendentes e o cônjuge do alienante expressamente consentirem.", "explicacao": "CC, art. 496."}, {"id": 2000001562, "trilha": "tribunais", "materia": "civ", "assunto": "Contratos", "tipo": "pergunta", "frente": "A doação de todos os bens é válida?", "verso": "Não, se o doador não reservar parte ou renda suficiente para sua subsistência.", "explicacao": "CC, art. 548."}, {"id": 2000001563, "trilha": "tribunais", "materia": "civ", "assunto": "Contratos", "tipo": "pergunta", "frente": "Quando a doação pode ser revogada?", "verso": "Por ingratidão do donatário ou por inexecução do encargo.", "explicacao": "CC, art. 555."}, {"id": 2000001564, "trilha": "tribunais", "materia": "civ", "assunto": "Contratos", "tipo": "pares", "frente": "Comodato x mútuo.", "verso": "Comodato: empréstimo gratuito de coisa infungível, que deve ser devolvida. Mútuo: empréstimo de coisa fungível, que transfere a propriedade e se devolve outra igual (dinheiro).", "explicacao": "CC, arts. 579 e 586."}, {"id": 2000001565, "trilha": "tribunais", "materia": "civ", "assunto": "Contratos", "tipo": "pergunta", "frente": "O fiador pode exigir que primeiro sejam executados os bens do devedor?", "verso": "Sim, é o benefício de ordem. Pode exigir que primeiro sejam executados os bens do devedor, salvo se renunciou expressamente ou se obrigou como principal pagador ou devedor solidário.", "explicacao": "CC, arts. 827 e 828."}, {"id": 2000001566, "trilha": "tribunais", "materia": "civ", "assunto": "Contratos", "tipo": "pergunta", "frente": "O contrato de fiança admite interpretação extensiva?", "verso": "Não. A fiança dá-se por escrito e não admite interpretação extensiva.", "explicacao": "CC, art. 819."}, {"id": 2000001567, "trilha": "tribunais", "materia": "civ", "assunto": "Responsabilidade civil", "tipo": "pergunta", "frente": "Qual a regra geral da responsabilidade civil no Código Civil?", "verso": "Quem, por ato ilícito, causar dano a outrem fica obrigado a repará-lo (responsabilidade subjetiva, com culpa).", "explicacao": "CC, arts. 186 e 927."}, {"id": 2000001568, "trilha": "tribunais", "materia": "civ", "assunto": "Responsabilidade civil", "tipo": "pergunta", "frente": "Quando a responsabilidade é objetiva no Código Civil?", "verso": "Nos casos especificados em lei ou quando a atividade normalmente desenvolvida pelo autor do dano implicar risco para os direitos de outrem.", "explicacao": "CC, art. 927, parágrafo único."}, {"id": 2000001569, "trilha": "tribunais", "materia": "civ", "assunto": "Responsabilidade civil", "tipo": "pergunta", "frente": "O que é abuso de direito?", "verso": "Exercer um direito excedendo manifestamente os limites impostos por seu fim econômico ou social, pela boa-fé ou pelos bons costumes. É ato ilícito.", "explicacao": "CC, art. 187."}, {"id": 2000001570, "trilha": "tribunais", "materia": "civ", "assunto": "Responsabilidade civil", "tipo": "pergunta", "frente": "Os pais respondem pelos danos causados pelos filhos menores?", "verso": "Sim, objetivamente, pelos filhos menores sob sua autoridade e em sua companhia.", "explicacao": "CC, arts. 932, I, e 933."}, {"id": 2000001571, "trilha": "tribunais", "materia": "civ", "assunto": "Responsabilidade civil", "tipo": "pergunta", "frente": "O empregador responde pelos atos de seus empregados?", "verso": "Sim, objetivamente, no exercício do trabalho ou em razão dele.", "explicacao": "CC, arts. 932, III, e 933."}, {"id": 2000001572, "trilha": "tribunais", "materia": "civ", "assunto": "Responsabilidade civil", "tipo": "pergunta", "frente": "Como se mede a indenização?", "verso": "Pela extensão do dano. Se houver excessiva desproporção entre a gravidade da culpa e o dano, o juiz pode reduzi-la equitativamente.", "explicacao": "CC, art. 944."}, {"id": 2000001573, "trilha": "tribunais", "materia": "civ", "assunto": "Responsabilidade civil", "tipo": "pergunta", "frente": "A responsabilidade civil depende da criminal?", "verso": "Não, são independentes; mas não se questiona mais sobre a existência do fato ou sua autoria quando decididas no juízo criminal.", "explicacao": "CC, art. 935."}, {"id": 2000001574, "trilha": "tribunais", "materia": "civ", "assunto": "Posse", "tipo": "pares", "frente": "Posse justa x injusta.", "verso": "Justa: não é violenta, clandestina nem precária. Injusta: adquirida com violência, clandestinidade ou precariedade.", "explicacao": "CC, art. 1.200."}, {"id": 2000001575, "trilha": "tribunais", "materia": "civ", "assunto": "Posse", "tipo": "pares", "frente": "Posse de boa-fé x má-fé.", "verso": "Boa-fé: o possuidor ignora o vício que impede a aquisição da coisa. Má-fé: conhece o vício.", "explicacao": "CC, art. 1.201."}, {"id": 2000001576, "trilha": "tribunais", "materia": "civ", "assunto": "Posse", "tipo": "pergunta", "frente": "Quais são as ações possessórias?", "verso": "Reintegração de posse (esbulho), manutenção de posse (turbação) e interdito proibitório (ameaça).", "explicacao": "CC, art. 1.210; CPC, arts. 554 e seguintes."}, {"id": 2000001577, "trilha": "tribunais", "materia": "civ", "assunto": "Posse", "tipo": "pergunta", "frente": "O possuidor de boa-fé tem direito às benfeitorias?", "verso": "Sim: indenização das necessárias e úteis, com direito de retenção, e pode levantar as voluptuárias se não forem pagas.", "explicacao": "CC, art. 1.219. O de má-fé só recebe as necessárias, sem retenção."}, {"id": 2000001578, "trilha": "tribunais", "materia": "civ", "assunto": "Propriedade", "tipo": "pergunta", "frente": "Quais os poderes do proprietário?", "verso": "Usar, gozar e dispor da coisa e reavê-la de quem injustamente a possua ou detenha.", "explicacao": "CC, art. 1.228."}, {"id": 2000001579, "trilha": "tribunais", "materia": "civ", "assunto": "Propriedade", "tipo": "pergunta", "frente": "Qual o prazo da usucapião extraordinária?", "verso": "15 anos, sem precisar de justo título e boa-fé; cai para 10 se o possuidor morar no imóvel ou nele fizer obras ou serviços produtivos.", "explicacao": "CC, art. 1.238."}, {"id": 2000001580, "trilha": "tribunais", "materia": "civ", "assunto": "Propriedade", "tipo": "pergunta", "frente": "Qual o prazo da usucapião ordinária?", "verso": "10 anos, com justo título e boa-fé; 5 anos se adquirido onerosamente com registro cancelado depois e houver moradia ou investimento.", "explicacao": "CC, art. 1.242."}, {"id": 2000001581, "trilha": "tribunais", "materia": "civ", "assunto": "Propriedade", "tipo": "pergunta", "frente": "Quais os requisitos da usucapião especial urbana?", "verso": "Área urbana de até 250 m², posse por 5 anos ininterruptos e sem oposição, para moradia, sem ser proprietário de outro imóvel.", "explicacao": "CF, art. 183; CC, art. 1.240."}, {"id": 2000001582, "trilha": "tribunais", "materia": "civ", "assunto": "Propriedade", "tipo": "pergunta", "frente": "Qual o prazo da usucapião familiar?", "verso": "2 anos, para quem ficou no imóvel urbano de até 250 m² abandonado pelo ex-cônjuge ou ex-companheiro.", "explicacao": "CC, art. 1.240-A."}, {"id": 2000001583, "trilha": "tribunais", "materia": "civ", "assunto": "Propriedade", "tipo": "pergunta", "frente": "Como se adquire a propriedade de imóvel por ato entre vivos?", "verso": "Pelo registro do título no Cartório de Registro de Imóveis.", "explicacao": "CC, art. 1.245."}, {"id": 2000001584, "trilha": "tribunais", "materia": "civ", "assunto": "Propriedade", "tipo": "pergunta", "frente": "Como se transfere a propriedade de bem móvel?", "verso": "Pela tradição (entrega).", "explicacao": "CC, art. 1.267."}, {"id": 2000001585, "trilha": "tribunais", "materia": "civ", "assunto": "Direitos reais", "tipo": "pergunta", "frente": "Quais são exemplos de direitos reais sobre coisa alheia?", "verso": "Superfície, servidões, usufruto, uso, habitação, direito do promitente comprador, penhor, hipoteca e anticrese, entre outros.", "explicacao": "CC, art. 1.225."}, {"id": 2000001586, "trilha": "tribunais", "materia": "civ", "assunto": "Direitos reais", "tipo": "pares", "frente": "Penhor x hipoteca x anticrese.", "verso": "Penhor: garantia sobre móvel, em regra com entrega da coisa. Hipoteca: garantia sobre imóvel (ou navios e aeronaves), sem entrega. Anticrese: o credor recebe os frutos do imóvel para pagar a dívida.", "explicacao": ""}, {"id": 2000001587, "trilha": "tribunais", "materia": "civ", "assunto": "Direitos reais", "tipo": "pergunta", "frente": "O usufruto pode ser transferido?", "verso": "Não pode ser alienado, mas seu exercício pode ser cedido a título gratuito ou oneroso.", "explicacao": "CC, art. 1.393."}, {"id": 2000001588, "trilha": "tribunais", "materia": "civ", "assunto": "Condomínio", "tipo": "pergunta", "frente": "Qual o limite da multa por atraso da contribuição condominial?", "verso": "Até 2% sobre o débito, além dos juros.", "explicacao": "CC, art. 1.336, § 1º."}, {"id": 2000001589, "trilha": "tribunais", "materia": "civ", "assunto": "Família", "tipo": "pergunta", "frente": "Qual a idade núbil?", "verso": "16 anos, com autorização dos pais enquanto não atingida a maioridade.", "explicacao": "CC, arts. 1.517 e 1.520 (proibido o casamento de menor de 16 anos)."}, {"id": 2000001590, "trilha": "tribunais", "materia": "civ", "assunto": "Família", "tipo": "pergunta", "frente": "Qual o regime de bens supletivo, se os noivos não escolherem?", "verso": "Comunhão parcial de bens.", "explicacao": "CC, art. 1.640."}, {"id": 2000001591, "trilha": "tribunais", "materia": "civ", "assunto": "Família", "tipo": "pares", "frente": "Comunhão parcial x comunhão universal x separação de bens.", "verso": "Parcial: comunicam-se os bens adquiridos onerosamente na constância do casamento. Universal: comunicam-se os bens presentes e futuros, com exceções. Separação: cada um mantém seus bens.", "explicacao": "Há ainda a participação final nos aquestos."}, {"id": 2000001592, "trilha": "tribunais", "materia": "civ", "assunto": "Família", "tipo": "pergunta", "frente": "Quem deve casar obrigatoriamente pelo regime da separação de bens?", "verso": "Os maiores de 70 anos, os que casarem com inobservância das causas suspensivas e quem depender de suprimento judicial para casar.", "explicacao": "CC, art. 1.641. O STF admitiu afastar a regra dos 70 anos por escritura pública (Tema 1.236)."}, {"id": 2000001593, "trilha": "tribunais", "materia": "civ", "assunto": "Família", "tipo": "pergunta", "frente": "Quais os requisitos da união estável?", "verso": "Convivência pública, contínua e duradoura, com objetivo de constituir família.", "explicacao": "CC, art. 1.723. Não exige tempo mínimo nem coabitação."}, {"id": 2000001594, "trilha": "tribunais", "materia": "civ", "assunto": "Família", "tipo": "pergunta", "frente": "Até quando dura o poder familiar?", "verso": "Enquanto os filhos forem menores (até 18 anos ou emancipação).", "explicacao": "CC, arts. 1.630 e 1.635."}, {"id": 2000001595, "trilha": "tribunais", "materia": "civ", "assunto": "Família", "tipo": "pergunta", "frente": "Qual o binômio que orienta a fixação dos alimentos?", "verso": "Necessidade de quem pede e possibilidade de quem paga (há quem fale em trinômio, com a proporcionalidade).", "explicacao": "CC, art. 1.694, § 1º."}, {"id": 2000001596, "trilha": "tribunais", "materia": "civ", "assunto": "Família", "tipo": "pergunta", "frente": "O direito a alimentos pode ser renunciado?", "verso": "Não. Pode-se deixar de exercê-lo, mas não renunciá-lo; o crédito é insuscetível de cessão, compensação ou penhora.", "explicacao": "CC, art. 1.707."}, {"id": 2000001597, "trilha": "tribunais", "materia": "civ", "assunto": "Família", "tipo": "pergunta", "frente": "O que é guarda compartilhada e quando é a regra?", "verso": "Responsabilização conjunta dos pais sobre os filhos; é a regra quando ambos estiverem aptos, salvo se um deles declarar que não deseja a guarda.", "explicacao": "CC, art. 1.584, § 2º."}, {"id": 2000001598, "trilha": "tribunais", "materia": "civ", "assunto": "Família", "tipo": "pergunta", "frente": "O divórcio exige prévia separação ou prazo?", "verso": "Não. Desde a EC 66/2010, o divórcio é direto e sem prazo.", "explicacao": "CF, art. 226, § 6º."}, {"id": 2000001599, "trilha": "tribunais", "materia": "civ", "assunto": "Sucessões", "tipo": "pergunta", "frente": "Quando se abre a sucessão?", "verso": "No momento da morte; a herança se transmite desde logo aos herdeiros (princípio da saisine).", "explicacao": "CC, art. 1.784."}, {"id": 2000001600, "trilha": "tribunais", "materia": "civ", "assunto": "Sucessões", "tipo": "pergunta", "frente": "Qual a ordem da vocação hereditária?", "verso": "1º descendentes (em concorrência com o cônjuge, conforme o regime); 2º ascendentes (em concorrência com o cônjuge); 3º cônjuge; 4º colaterais até o 4º grau.", "explicacao": "CC, art. 1.829."}, {"id": 2000001601, "trilha": "tribunais", "materia": "civ", "assunto": "Sucessões", "tipo": "pergunta", "frente": "Quem são os herdeiros necessários?", "verso": "Descendentes, ascendentes e cônjuge.", "explicacao": "CC, art. 1.845. O STF equiparou o companheiro para fins sucessórios (Tema 809)."}, {"id": 2000001602, "trilha": "tribunais", "materia": "civ", "assunto": "Sucessões", "tipo": "pergunta", "frente": "Quanto o testador pode dispor livremente se tiver herdeiros necessários?", "verso": "Metade da herança; a outra metade (legítima) pertence aos herdeiros necessários.", "explicacao": "CC, arts. 1.789 e 1.846."}, {"id": 2000001603, "trilha": "tribunais", "materia": "civ", "assunto": "Sucessões", "tipo": "pares", "frente": "Indignidade x deserdação.", "verso": "Indignidade: exclusão por sentença em ação proposta pelos interessados, por atos graves contra o autor da herança. Deserdação: feita pelo próprio testador, em testamento, com causa expressa.", "explicacao": "CC, arts. 1.814 e 1.961."}, {"id": 2000001604, "trilha": "tribunais", "materia": "civ", "assunto": "Sucessões", "tipo": "pergunta", "frente": "A renúncia à herança pode ser tácita?", "verso": "Não. Deve constar expressamente de instrumento público ou termo judicial.", "explicacao": "CC, art. 1.806."}, {"id": 2000001605, "trilha": "tribunais", "materia": "civ", "assunto": "Sucessões", "tipo": "pergunta", "frente": "Quais são os testamentos ordinários?", "verso": "Público, cerrado e particular.", "explicacao": "CC, art. 1.862."}, {"id": 2000001606, "trilha": "tribunais", "materia": "civ", "assunto": "Sucessões", "tipo": "pergunta", "frente": "O que é direito de representação?", "verso": "Quando a lei chama parentes do falecido a suceder em todos os direitos em que ele sucederia se vivo fosse.", "explicacao": "CC, art. 1.851. Ocorre na linha descendente, nunca na ascendente."}, {"id": 2000001607, "trilha": "tribunais", "materia": "civ", "assunto": "Sucessões", "tipo": "pergunta", "frente": "Quem é o primeiro na ordem para ser inventariante?", "verso": "O cônjuge ou companheiro sobrevivente que convivia com o falecido.", "explicacao": "CPC, art. 617, I."}, {"id": 2000001608, "trilha": "tribunais", "materia": "civ", "assunto": "Sucessões", "tipo": "pergunta", "frente": "Qual o prazo para abrir o inventário?", "verso": "2 meses a contar da abertura da sucessão, com término nos 12 meses seguintes.", "explicacao": "CPC, art. 611."}, {"id": 2000001609, "trilha": "tribunais", "materia": "civ", "assunto": "Consumidor", "tipo": "pergunta", "frente": "Qual a regra da responsabilidade do fornecedor no CDC?", "verso": "Responsabilidade objetiva pelo fato e pelo vício do produto ou serviço.", "explicacao": "CDC, arts. 12, 14 e 18."}, {"id": 2000001610, "trilha": "tribunais", "materia": "civ", "assunto": "Consumidor", "tipo": "pergunta", "frente": "Qual o prazo de arrependimento em compras fora do estabelecimento?", "verso": "7 dias, a contar da assinatura ou do recebimento do produto ou serviço.", "explicacao": "CDC, art. 49."}, {"id": 2000001611, "trilha": "tribunais", "materia": "pciv", "assunto": "Normas fundamentais", "tipo": "pergunta", "frente": "O processo civil começa como e se desenvolve como?", "verso": "Começa por iniciativa da parte e se desenvolve por impulso oficial, salvo exceções previstas em lei.", "explicacao": "CPC, art. 2º."}, {"id": 2000001612, "trilha": "tribunais", "materia": "pciv", "assunto": "Normas fundamentais", "tipo": "pergunta", "frente": "O juiz pode decidir com base em fundamento sobre o qual as partes não puderam se manifestar?", "verso": "Não, ainda que se trate de matéria que deva decidir de ofício (vedação da decisão surpresa).", "explicacao": "CPC, art. 10."}, {"id": 2000001613, "trilha": "tribunais", "materia": "pciv", "assunto": "Normas fundamentais", "tipo": "pergunta", "frente": "O que diz o princípio da cooperação no CPC?", "verso": "Todos os sujeitos do processo devem cooperar entre si para obter, em tempo razoável, decisão de mérito justa e efetiva.", "explicacao": "CPC, art. 6º."}, {"id": 2000001614, "trilha": "tribunais", "materia": "pciv", "assunto": "Normas fundamentais", "tipo": "pergunta", "frente": "Qual a regra sobre a ordem de julgamento dos processos?", "verso": "Juízes e tribunais devem atender, preferencialmente, à ordem cronológica de conclusão para proferir sentença ou acórdão.", "explicacao": "CPC, art. 12."}, {"id": 2000001615, "trilha": "tribunais", "materia": "pciv", "assunto": "Normas fundamentais", "tipo": "pergunta", "frente": "O Estado deve promover a solução consensual dos conflitos?", "verso": "Sim, sempre que possível; conciliação e mediação devem ser estimuladas por juízes, advogados, defensores e MP.", "explicacao": "CPC, art. 3º, §§ 2º e 3º."}, {"id": 2000001616, "trilha": "tribunais", "materia": "pciv", "assunto": "Jurisdição e ação", "tipo": "pergunta", "frente": "Quais são, no CPC atual, os requisitos para postular em juízo?", "verso": "Interesse e legitimidade.", "explicacao": "CPC, art. 17. A possibilidade jurídica do pedido deixou de ser condição autônoma."}, {"id": 2000001617, "trilha": "tribunais", "materia": "pciv", "assunto": "Jurisdição e ação", "tipo": "pergunta", "frente": "Alguém pode pleitear direito alheio em nome próprio?", "verso": "Só quando autorizado pelo ordenamento jurídico (legitimação extraordinária).", "explicacao": "CPC, art. 18."}, {"id": 2000001618, "trilha": "tribunais", "materia": "pciv", "assunto": "Competência", "tipo": "pares", "frente": "Competência absoluta x relativa.", "verso": "Absoluta: em razão da matéria, da pessoa ou funcional; não se prorroga e pode ser declarada de ofício. Relativa: em razão do valor ou do território; prorroga-se se não alegada em preliminar de contestação.", "explicacao": "CPC, arts. 62 a 65."}, {"id": 2000001619, "trilha": "tribunais", "materia": "pciv", "assunto": "Competência", "tipo": "pergunta", "frente": "O juiz pode declarar de ofício a incompetência relativa?", "verso": "Não. Mas pode reconhecer de ofício a abusividade da cláusula de eleição de foro antes da citação.", "explicacao": "CPC, art. 63, § 3º; Súmula 33 do STJ."}, {"id": 2000001620, "trilha": "tribunais", "materia": "pciv", "assunto": "Competência", "tipo": "pergunta", "frente": "Qual o foro competente, em regra, para ações sobre direito pessoal e direito real sobre móveis?", "verso": "O domicílio do réu.", "explicacao": "CPC, art. 46."}, {"id": 2000001621, "trilha": "tribunais", "materia": "pciv", "assunto": "Competência", "tipo": "pergunta", "frente": "Qual o foro para ações sobre direito real sobre imóveis?", "verso": "O da situação da coisa.", "explicacao": "CPC, art. 47."}, {"id": 2000001622, "trilha": "tribunais", "materia": "pciv", "assunto": "Competência", "tipo": "pergunta", "frente": "Qual o foro da ação de alimentos?", "verso": "O domicílio ou residência do alimentando.", "explicacao": "CPC, art. 53, II."}, {"id": 2000001623, "trilha": "tribunais", "materia": "pciv", "assunto": "Competência", "tipo": "pergunta", "frente": "Como se alega a incompetência, absoluta ou relativa, no CPC atual?", "verso": "Como questão preliminar de contestação.", "explicacao": "CPC, art. 64. Acabou a exceção de incompetência em peça separada."}, {"id": 2000001624, "trilha": "tribunais", "materia": "pciv", "assunto": "Competência", "tipo": "pares", "frente": "Conexão x continência.", "verso": "Conexão: duas ou mais ações com o mesmo pedido ou causa de pedir. Continência: identidade de partes e causa de pedir, e o pedido de uma, por ser mais amplo, abrange o da outra.", "explicacao": "CPC, arts. 55 e 56."}, {"id": 2000001625, "trilha": "tribunais", "materia": "pciv", "assunto": "Competência", "tipo": "pergunta", "frente": "Qual juízo fica prevento entre ações conexas?", "verso": "O juízo em que primeiro foi registrada ou distribuída a petição inicial.", "explicacao": "CPC, art. 59."}, {"id": 2000001626, "trilha": "tribunais", "materia": "pciv", "assunto": "Sujeitos", "tipo": "pergunta", "frente": "Quais os deveres da parte e de seu procurador?", "verso": "Expor os fatos conforme a verdade, não formular pretensão destituída de fundamento, não produzir provas inúteis, cumprir decisões e não criar embaraços, entre outros.", "explicacao": "CPC, art. 77."}, {"id": 2000001627, "trilha": "tribunais", "materia": "pciv", "assunto": "Sujeitos", "tipo": "pergunta", "frente": "Qual a multa por litigância de má-fé?", "verso": "Superior a 1% e inferior a 10% do valor corrigido da causa, além de indenização e honorários.", "explicacao": "CPC, art. 81."}, {"id": 2000001628, "trilha": "tribunais", "materia": "pciv", "assunto": "Sujeitos", "tipo": "pergunta", "frente": "Qual a faixa dos honorários de sucumbência em regra?", "verso": "Entre 10% e 20% sobre o valor da condenação, do proveito econômico ou, não sendo possível mensurá-lo, do valor atualizado da causa.", "explicacao": "CPC, art. 85, § 2º."}, {"id": 2000001629, "trilha": "tribunais", "materia": "pciv", "assunto": "Sujeitos", "tipo": "pergunta", "frente": "A gratuidade da justiça pode ser pedida a qualquer tempo?", "verso": "Sim: na petição inicial, na contestação, na petição de ingresso de terceiro ou em recurso.", "explicacao": "CPC, art. 99."}, {"id": 2000001630, "trilha": "tribunais", "materia": "pciv", "assunto": "Sujeitos", "tipo": "pergunta", "frente": "A declaração de insuficiência da pessoa natural tem presunção de veracidade?", "verso": "Sim, presume-se verdadeira a alegação de insuficiência deduzida exclusivamente por pessoa natural.", "explicacao": "CPC, art. 99, § 3º."}, {"id": 2000001631, "trilha": "tribunais", "materia": "pciv", "assunto": "Sujeitos", "tipo": "pares", "frente": "Impedimento x suspeição do juiz.", "verso": "Impedimento: hipóteses objetivas (atuou como advogado, parente é parte etc.), presunção absoluta, cabe ação rescisória. Suspeição: hipóteses subjetivas (amigo íntimo, inimigo, interessado), pode declarar-se por foro íntimo.", "explicacao": "CPC, arts. 144 e 145."}, {"id": 2000001632, "trilha": "tribunais", "materia": "pciv", "assunto": "Sujeitos", "tipo": "pergunta", "frente": "O MP intervém como fiscal da ordem jurídica em quais processos?", "verso": "Nos que envolvam interesse público ou social, interesse de incapaz e litígios coletivos pela posse de terra rural ou urbana.", "explicacao": "CPC, art. 178."}, {"id": 2000001633, "trilha": "tribunais", "materia": "pciv", "assunto": "Sujeitos", "tipo": "pergunta", "frente": "A Fazenda Pública, o MP e a Defensoria têm prazo diferenciado?", "verso": "Sim, prazo em dobro para todas as manifestações processuais.", "explicacao": "CPC, arts. 180, 183 e 186."}, {"id": 2000001634, "trilha": "tribunais", "materia": "pciv", "assunto": "Litisconsórcio", "tipo": "pares", "frente": "Litisconsórcio necessário x unitário.", "verso": "Necessário: a presença de todos é obrigatória, por lei ou pela natureza da relação. Unitário: a decisão deve ser uniforme para todos.", "explicacao": "CPC, arts. 114 e 116."}, {"id": 2000001635, "trilha": "tribunais", "materia": "pciv", "assunto": "Litisconsórcio", "tipo": "pergunta", "frente": "Litisconsortes com advogados diferentes, de escritórios distintos, têm prazo em dobro?", "verso": "Sim, em autos físicos. Não se aplica a processos em autos eletrônicos.", "explicacao": "CPC, art. 229."}, {"id": 2000001636, "trilha": "tribunais", "materia": "pciv", "assunto": "Intervenção de terceiros", "tipo": "pergunta", "frente": "Quais são as modalidades de intervenção de terceiros no CPC?", "verso": "Assistência, denunciação da lide, chamamento ao processo, incidente de desconsideração da personalidade jurídica e amicus curiae.", "explicacao": "CPC, arts. 119 a 138."}, {"id": 2000001637, "trilha": "tribunais", "materia": "pciv", "assunto": "Intervenção de terceiros", "tipo": "pares", "frente": "Denunciação da lide x chamamento ao processo.", "verso": "Denunciação: traz quem deve indenizar a parte em ação regressiva (evicção, garantia). Chamamento: traz codevedores solidários ou o devedor principal (pelo fiador).", "explicacao": "CPC, arts. 125 e 130."}, {"id": 2000001638, "trilha": "tribunais", "materia": "pciv", "assunto": "Intervenção de terceiros", "tipo": "pergunta", "frente": "Cabe recurso da decisão que admite ou inadmite o amicus curiae?", "verso": "Em regra, não; pode apenas opor embargos de declaração e recorrer da decisão que julgar o IRDR.", "explicacao": "CPC, art. 138, §§ 1º e 3º."}, {"id": 2000001639, "trilha": "tribunais", "materia": "pciv", "assunto": "Atos processuais", "tipo": "pergunta", "frente": "Como se contam os prazos processuais no CPC?", "verso": "Em dias úteis.", "explicacao": "CPC, art. 219. Só os prazos processuais."}, {"id": 2000001640, "trilha": "tribunais", "materia": "pciv", "assunto": "Atos processuais", "tipo": "pergunta", "frente": "Qual o período de suspensão dos prazos no fim do ano?", "verso": "De 20 de dezembro a 20 de janeiro.", "explicacao": "CPC, art. 220."}, {"id": 2000001641, "trilha": "tribunais", "materia": "pciv", "assunto": "Atos processuais", "tipo": "pergunta", "frente": "Qual o prazo para a parte praticar ato quando não houver prazo fixado em lei ou pelo juiz?", "verso": "5 dias.", "explicacao": "CPC, art. 218, § 3º."}, {"id": 2000001642, "trilha": "tribunais", "materia": "pciv", "assunto": "Atos processuais", "tipo": "pergunta", "frente": "O que é negócio jurídico processual?", "verso": "Acordo entre partes plenamente capazes, em causa que admite autocomposição, para ajustar o procedimento e convencionar ônus, poderes, faculdades e deveres processuais.", "explicacao": "CPC, art. 190."}, {"id": 2000001643, "trilha": "tribunais", "materia": "pciv", "assunto": "Atos processuais", "tipo": "pergunta", "frente": "Quais os prazos do juiz no CPC?", "verso": "Despachos: 5 dias. Decisões interlocutórias: 10 dias. Sentenças: 30 dias.", "explicacao": "CPC, art. 226."}, {"id": 2000001644, "trilha": "tribunais", "materia": "pciv", "assunto": "Comunicação", "tipo": "pergunta", "frente": "Qual a forma preferencial de citação no CPC?", "verso": "Por meio eletrônico, em até 2 dias úteis da decisão que a determinar.", "explicacao": "CPC, art. 246, com a Lei 14.195/2021."}, {"id": 2000001645, "trilha": "tribunais", "materia": "pciv", "assunto": "Comunicação", "tipo": "pergunta", "frente": "O que é a citação com hora certa?", "verso": "Quando o oficial procura o réu duas vezes sem encontrá-lo e há suspeita de ocultação, intima pessoa da família ou vizinho de que voltará no dia seguinte, em hora designada.", "explicacao": "CPC, art. 252."}, {"id": 2000001646, "trilha": "tribunais", "materia": "pciv", "assunto": "Comunicação", "tipo": "pergunta", "frente": "Quando cabe a citação por edital?", "verso": "Quando desconhecido ou incerto o citando, quando ignorado, incerto ou inacessível o lugar em que se encontrar, e nos casos previstos em lei.", "explicacao": "CPC, art. 256."}, {"id": 2000001647, "trilha": "tribunais", "materia": "pciv", "assunto": "Comunicação", "tipo": "pergunta", "frente": "Quais os efeitos da citação válida?", "verso": "Induz litispendência, torna litigiosa a coisa e constitui o devedor em mora.", "explicacao": "CPC, art. 240. A interrupção da prescrição retroage à propositura da ação."}, {"id": 2000001648, "trilha": "tribunais", "materia": "pciv", "assunto": "Tutela provisória", "tipo": "pares", "frente": "Tutela de urgência x de evidência.", "verso": "Urgência: exige probabilidade do direito e perigo de dano ou risco ao resultado útil do processo. Evidência: independe de perigo de dano, nas hipóteses do art. 311.", "explicacao": "CPC, arts. 300 e 311."}, {"id": 2000001649, "trilha": "tribunais", "materia": "pciv", "assunto": "Tutela provisória", "tipo": "pares", "frente": "Tutela antecipada x cautelar.", "verso": "Antecipada: satisfativa, adianta o próprio direito pedido. Cautelar: assegura o resultado útil do processo (arresto, sequestro).", "explicacao": "Ambas são tutelas de urgência."}, {"id": 2000001650, "trilha": "tribunais", "materia": "pciv", "assunto": "Tutela provisória", "tipo": "pergunta", "frente": "O que acontece se o réu não recorrer da tutela antecipada antecedente?", "verso": "Ela se torna estável e o processo é extinto.", "explicacao": "CPC, art. 304. Qualquer parte pode pedir sua revisão em 2 anos."}, {"id": 2000001651, "trilha": "tribunais", "materia": "pciv", "assunto": "Tutela provisória", "tipo": "pergunta", "frente": "A tutela de urgência antecipada pode ser concedida se houver perigo de irreversibilidade?", "verso": "Não, quando houver perigo de irreversibilidade dos efeitos da decisão.", "explicacao": "CPC, art. 300, § 3º."}, {"id": 2000001652, "trilha": "tribunais", "materia": "pciv", "assunto": "Tutela provisória", "tipo": "pergunta", "frente": "Cite uma hipótese de tutela da evidência que pode ser concedida liminarmente.", "verso": "Quando as alegações puderem ser comprovadas documentalmente e houver tese firmada em casos repetitivos ou súmula vinculante; ou pedido reipersecutório fundado em contrato de depósito.", "explicacao": "CPC, art. 311, II e III, e parágrafo único."}, {"id": 2000001653, "trilha": "tribunais", "materia": "pciv", "assunto": "Petição inicial", "tipo": "pergunta", "frente": "Quais os requisitos da petição inicial?", "verso": "Juízo, qualificação das partes, fatos e fundamentos jurídicos, pedido com suas especificações, valor da causa, provas e opção pela audiência de conciliação ou mediação.", "explicacao": "CPC, art. 319."}, {"id": 2000001654, "trilha": "tribunais", "materia": "pciv", "assunto": "Petição inicial", "tipo": "pergunta", "frente": "Qual o prazo para emendar a petição inicial?", "verso": "15 dias.", "explicacao": "CPC, art. 321."}, {"id": 2000001655, "trilha": "tribunais", "materia": "pciv", "assunto": "Petição inicial", "tipo": "pergunta", "frente": "Quando o juiz pode julgar liminarmente improcedente o pedido?", "verso": "Nas causas que dispensem instrução, quando o pedido contrariar súmula do STF ou STJ, acórdão em repetitivos, IRDR ou IAC, súmula de TJ sobre direito local, ou houver prescrição ou decadência.", "explicacao": "CPC, art. 332."}, {"id": 2000001656, "trilha": "tribunais", "materia": "pciv", "assunto": "Petição inicial", "tipo": "pergunta", "frente": "O pedido deve ser certo e determinado?", "verso": "Sim, mas admite-se pedido genérico em ações universais, quando não for possível determinar as consequências do ato ou quando o valor depender de ato do réu.", "explicacao": "CPC, arts. 322, 324."}, {"id": 2000001657, "trilha": "tribunais", "materia": "pciv", "assunto": "Procedimento comum", "tipo": "pergunta", "frente": "Com que antecedência mínima se designa a audiência de conciliação ou mediação?", "verso": "Com antecedência mínima de 30 dias, citando-se o réu com pelo menos 20 dias de antecedência.", "explicacao": "CPC, art. 334."}, {"id": 2000001658, "trilha": "tribunais", "materia": "pciv", "assunto": "Procedimento comum", "tipo": "pergunta", "frente": "Quando a audiência de conciliação não será realizada?", "verso": "Se ambas as partes manifestarem desinteresse expresso na autocomposição, ou quando não se admitir autocomposição.", "explicacao": "CPC, art. 334, § 4º."}, {"id": 2000001659, "trilha": "tribunais", "materia": "pciv", "assunto": "Procedimento comum", "tipo": "pergunta", "frente": "Qual a consequência do não comparecimento injustificado à audiência de conciliação?", "verso": "É ato atentatório à dignidade da justiça, com multa de até 2% da vantagem econômica pretendida ou do valor da causa.", "explicacao": "CPC, art. 334, § 8º."}, {"id": 2000001660, "trilha": "tribunais", "materia": "pciv", "assunto": "Resposta do réu", "tipo": "pergunta", "frente": "Qual o prazo da contestação no procedimento comum?", "verso": "15 dias (úteis).", "explicacao": "CPC, art. 335."}, {"id": 2000001661, "trilha": "tribunais", "materia": "pciv", "assunto": "Resposta do réu", "tipo": "pergunta", "frente": "O que é o princípio da eventualidade (concentração da defesa)?", "verso": "O réu deve alegar na contestação toda a matéria de defesa.", "explicacao": "CPC, art. 336."}, {"id": 2000001662, "trilha": "tribunais", "materia": "pciv", "assunto": "Resposta do réu", "tipo": "pergunta", "frente": "Como o réu faz reconvenção no CPC atual?", "verso": "Na própria contestação.", "explicacao": "CPC, art. 343."}, {"id": 2000001663, "trilha": "tribunais", "materia": "pciv", "assunto": "Resposta do réu", "tipo": "pergunta", "frente": "Qual o principal efeito da revelia?", "verso": "Presumem-se verdadeiras as alegações de fato formuladas pelo autor.", "explicacao": "CPC, art. 344."}, {"id": 2000001664, "trilha": "tribunais", "materia": "pciv", "assunto": "Resposta do réu", "tipo": "pergunta", "frente": "Em quais casos a revelia não produz o efeito de presunção de veracidade?", "verso": "Se algum litisconsorte contestar; se o litígio versar sobre direitos indisponíveis; se faltar instrumento indispensável; ou se as alegações forem inverossímeis ou contrariadas pela prova.", "explicacao": "CPC, art. 345."}, {"id": 2000001665, "trilha": "tribunais", "materia": "pciv", "assunto": "Julgamento conforme o estado do processo", "tipo": "pares", "frente": "Julgamento antecipado total x parcial do mérito.", "verso": "Total: quando não houver necessidade de outras provas ou ocorrer revelia com presunção de veracidade. Parcial: quando um ou mais pedidos forem incontroversos ou estiverem em condições de imediato julgamento.", "explicacao": "CPC, arts. 355 e 356."}, {"id": 2000001666, "trilha": "tribunais", "materia": "pciv", "assunto": "Julgamento conforme o estado do processo", "tipo": "pergunta", "frente": "Qual o recurso cabível contra o julgamento antecipado parcial do mérito?", "verso": "Agravo de instrumento.", "explicacao": "CPC, art. 356, § 5º."}, {"id": 2000001667, "trilha": "tribunais", "materia": "pciv", "assunto": "Provas", "tipo": "pergunta", "frente": "Como se distribui o ônus da prova em regra?", "verso": "Ao autor, quanto ao fato constitutivo do seu direito; ao réu, quanto aos fatos impeditivos, modificativos ou extintivos.", "explicacao": "CPC, art. 373."}, {"id": 2000001668, "trilha": "tribunais", "materia": "pciv", "assunto": "Provas", "tipo": "pergunta", "frente": "O juiz pode distribuir o ônus da prova de modo diverso?", "verso": "Sim, por decisão fundamentada, diante de impossibilidade ou excessiva dificuldade de cumprir o encargo ou maior facilidade de obter a prova do fato contrário (carga dinâmica).", "explicacao": "CPC, art. 373, § 1º."}, {"id": 2000001669, "trilha": "tribunais", "materia": "pciv", "assunto": "Provas", "tipo": "pergunta", "frente": "Quais fatos não dependem de prova?", "verso": "Notórios, afirmados por uma parte e confessados pela outra, admitidos como incontroversos e aqueles em cujo favor milita presunção legal.", "explicacao": "CPC, art. 374."}, {"id": 2000001670, "trilha": "tribunais", "materia": "pciv", "assunto": "Provas", "tipo": "pergunta", "frente": "Quantas testemunhas cada parte pode arrolar?", "verso": "Até 10, sendo no máximo 3 para a prova de cada fato.", "explicacao": "CPC, art. 357, § 6º."}, {"id": 2000001671, "trilha": "tribunais", "materia": "pciv", "assunto": "Provas", "tipo": "pergunta", "frente": "Quem é responsável por intimar a testemunha no CPC?", "verso": "O advogado da parte, por carta com aviso de recebimento.", "explicacao": "CPC, art. 455."}, {"id": 2000001672, "trilha": "tribunais", "materia": "pciv", "assunto": "Provas", "tipo": "pergunta", "frente": "O que é prova emprestada?", "verso": "Prova produzida em outro processo e trazida ao atual, observado o contraditório.", "explicacao": "CPC, art. 372."}, {"id": 2000001673, "trilha": "tribunais", "materia": "pciv", "assunto": "Sentença", "tipo": "pares", "frente": "Sentença terminativa x definitiva.", "verso": "Terminativa: extingue o processo sem resolver o mérito (art. 485). Definitiva: resolve o mérito (art. 487).", "explicacao": ""}, {"id": 2000001674, "trilha": "tribunais", "materia": "pciv", "assunto": "Sentença", "tipo": "pergunta", "frente": "Cite hipóteses de extinção sem resolução do mérito.", "verso": "Indeferimento da inicial, abandono, ausência de pressupostos processuais, perempção, litispendência ou coisa julgada, falta de legitimidade ou interesse, convenção de arbitragem, desistência.", "explicacao": "CPC, art. 485."}, {"id": 2000001675, "trilha": "tribunais", "materia": "pciv", "assunto": "Sentença", "tipo": "pergunta", "frente": "Quais os elementos essenciais da sentença?", "verso": "Relatório, fundamentos e dispositivo.", "explicacao": "CPC, art. 489."}, {"id": 2000001676, "trilha": "tribunais", "materia": "pciv", "assunto": "Sentença", "tipo": "pergunta", "frente": "O que é perempção?", "verso": "Perda do direito de ação quando o autor der causa, por 3 vezes, à extinção do processo por abandono.", "explicacao": "CPC, art. 486, § 3º. Pode alegar o direito em defesa."}, {"id": 2000001677, "trilha": "tribunais", "materia": "pciv", "assunto": "Sentença", "tipo": "pergunta", "frente": "Quando a sentença está sujeita à remessa necessária?", "verso": "Quando proferida contra a União, estados, DF, municípios e suas autarquias e fundações, ou quando julgar procedentes embargos à execução fiscal, observados os limites de valor.", "explicacao": "CPC, art. 496."}, {"id": 2000001678, "trilha": "tribunais", "materia": "pciv", "assunto": "Sentença", "tipo": "pergunta", "frente": "Quais os limites de valor que dispensam a remessa necessária?", "verso": "Condenação ou proveito inferior a 1.000 salários mínimos para a União; 500 para estados, DF e capitais; 100 para os demais municípios.", "explicacao": "CPC, art. 496, § 3º."}, {"id": 2000001679, "trilha": "tribunais", "materia": "pciv", "assunto": "Coisa julgada", "tipo": "pergunta", "frente": "O que faz coisa julgada: o dispositivo ou os motivos da sentença?", "verso": "O dispositivo. Os motivos e a verdade dos fatos não fazem coisa julgada.", "explicacao": "CPC, art. 504."}, {"id": 2000001680, "trilha": "tribunais", "materia": "pciv", "assunto": "Coisa julgada", "tipo": "pergunta", "frente": "A questão prejudicial decidida incidentalmente faz coisa julgada?", "verso": "Sim, se dela depender o julgamento do mérito, houver contraditório prévio e efetivo e o juízo for competente para resolvê-la como questão principal.", "explicacao": "CPC, art. 503, § 1º."}, {"id": 2000001681, "trilha": "tribunais", "materia": "pciv", "assunto": "Coisa julgada", "tipo": "pergunta", "frente": "Qual o prazo da ação rescisória?", "verso": "2 anos, contados do trânsito em julgado da última decisão no processo.", "explicacao": "CPC, art. 975."}, {"id": 2000001682, "trilha": "tribunais", "materia": "pciv", "assunto": "Recursos", "tipo": "pergunta", "frente": "Qual o prazo geral dos recursos no CPC?", "verso": "15 dias úteis, exceto os embargos de declaração (5 dias).", "explicacao": "CPC, art. 1.003, § 5º."}, {"id": 2000001683, "trilha": "tribunais", "materia": "pciv", "assunto": "Recursos", "tipo": "pergunta", "frente": "Quais são os recursos previstos no CPC?", "verso": "Apelação, agravo de instrumento, agravo interno, embargos de declaração, recurso ordinário, recurso especial, recurso extraordinário, agravo em REsp ou RE e embargos de divergência.", "explicacao": "CPC, art. 994."}, {"id": 2000001684, "trilha": "tribunais", "materia": "pciv", "assunto": "Recursos", "tipo": "pergunta", "frente": "Em regra, a apelação tem efeito suspensivo?", "verso": "Sim, salvo nas hipóteses do art. 1.012, § 1º (como sentença que condena a pagar alimentos ou que confirma tutela provisória).", "explicacao": "CPC, art. 1.012."}, {"id": 2000001685, "trilha": "tribunais", "materia": "pciv", "assunto": "Recursos", "tipo": "pergunta", "frente": "O agravo de instrumento cabe contra qualquer decisão interlocutória?", "verso": "Não. Só nas hipóteses do art. 1.015 (rol de taxatividade mitigada, segundo o STJ, quando houver urgência).", "explicacao": "CPC, art. 1.015; STJ, Tema 988."}, {"id": 2000001686, "trilha": "tribunais", "materia": "pciv", "assunto": "Recursos", "tipo": "pergunta", "frente": "Como se impugnam as interlocutórias que não admitem agravo de instrumento?", "verso": "Em preliminar de apelação ou nas contrarrazões.", "explicacao": "CPC, art. 1.009, § 1º."}, {"id": 2000001687, "trilha": "tribunais", "materia": "pciv", "assunto": "Recursos", "tipo": "pergunta", "frente": "Para que servem os embargos de declaração?", "verso": "Esclarecer obscuridade, eliminar contradição, suprir omissão e corrigir erro material.", "explicacao": "CPC, art. 1.022."}, {"id": 2000001688, "trilha": "tribunais", "materia": "pciv", "assunto": "Recursos", "tipo": "pergunta", "frente": "Os embargos de declaração interrompem o prazo de outros recursos?", "verso": "Sim, interrompem o prazo para interposição de recurso.", "explicacao": "CPC, art. 1.026."}, {"id": 2000001689, "trilha": "tribunais", "materia": "pciv", "assunto": "Recursos", "tipo": "pergunta", "frente": "Qual a multa por embargos de declaração manifestamente protelatórios?", "verso": "Até 2% do valor atualizado da causa; na reiteração, até 10%.", "explicacao": "CPC, art. 1.026, §§ 2º e 3º."}, {"id": 2000001690, "trilha": "tribunais", "materia": "pciv", "assunto": "Recursos", "tipo": "pergunta", "frente": "Contra qual decisão cabe agravo interno?", "verso": "Contra decisão proferida pelo relator, para o respectivo órgão colegiado.", "explicacao": "CPC, art. 1.021."}, {"id": 2000001691, "trilha": "tribunais", "materia": "pciv", "assunto": "Recursos", "tipo": "pergunta", "frente": "O que é a teoria da causa madura na apelação?", "verso": "Se o processo estiver em condições de imediato julgamento, o tribunal decide desde logo o mérito, mesmo reformando sentença terminativa.", "explicacao": "CPC, art. 1.013, § 3º."}, {"id": 2000001692, "trilha": "tribunais", "materia": "pciv", "assunto": "Recursos", "tipo": "pergunta", "frente": "O que é a técnica de ampliação do colegiado?", "verso": "Quando o julgamento da apelação não for unânime, prossegue com outros julgadores em número suficiente para inverter o resultado.", "explicacao": "CPC, art. 942. Substituiu os embargos infringentes."}, {"id": 2000001693, "trilha": "tribunais", "materia": "pciv", "assunto": "Recursos", "tipo": "pares", "frente": "Recurso especial x extraordinário.", "verso": "Especial (STJ): violação de lei federal ou divergência na interpretação de lei federal entre tribunais. Extraordinário (STF): contrariedade à Constituição, exigindo repercussão geral.", "explicacao": "CF, arts. 102, III, e 105, III."}, {"id": 2000001694, "trilha": "tribunais", "materia": "pciv", "assunto": "Recursos", "tipo": "pergunta", "frente": "O preparo do recurso deve ser comprovado quando?", "verso": "No ato de interposição; se insuficiente, o recorrente é intimado para complementar em 5 dias.", "explicacao": "CPC, art. 1.007, § 2º. Sem recolhimento, pagamento em dobro."}, {"id": 2000001695, "trilha": "tribunais", "materia": "pciv", "assunto": "Precedentes", "tipo": "pergunta", "frente": "O que é o IRDR?", "verso": "Incidente de resolução de demandas repetitivas: cabível quando houver repetição de processos com a mesma questão de direito e risco à isonomia e segurança jurídica.", "explicacao": "CPC, art. 976."}, {"id": 2000001696, "trilha": "tribunais", "materia": "pciv", "assunto": "Precedentes", "tipo": "pergunta", "frente": "O que os juízes e tribunais devem observar obrigatoriamente?", "verso": "Decisões do STF em controle concentrado, súmulas vinculantes, acórdãos em IAC, IRDR e repetitivos, súmulas do STF e STJ e orientação do plenário ou órgão especial a que estiverem vinculados.", "explicacao": "CPC, art. 927."}, {"id": 2000001697, "trilha": "tribunais", "materia": "pciv", "assunto": "Cumprimento de sentença", "tipo": "pergunta", "frente": "Qual o prazo para pagar voluntariamente no cumprimento de sentença de quantia certa?", "verso": "15 dias, sob pena de multa de 10% e honorários de 10%.", "explicacao": "CPC, art. 523."}, {"id": 2000001698, "trilha": "tribunais", "materia": "pciv", "assunto": "Cumprimento de sentença", "tipo": "pergunta", "frente": "Como o executado se defende no cumprimento de sentença?", "verso": "Por impugnação, em 15 dias após o prazo para pagamento voluntário, independentemente de penhora.", "explicacao": "CPC, art. 525."}, {"id": 2000001699, "trilha": "tribunais", "materia": "pciv", "assunto": "Cumprimento de sentença", "tipo": "pergunta", "frente": "Quais as formas de execução de alimentos?", "verso": "Pelo rito da prisão civil (até as 3 prestações anteriores ao ajuizamento e as que vencerem no curso) ou pelo rito da penhora.", "explicacao": "CPC, art. 528; Súmula 309 do STJ."}, {"id": 2000001700, "trilha": "tribunais", "materia": "pciv", "assunto": "Cumprimento de sentença", "tipo": "pergunta", "frente": "Qual o prazo da prisão civil do devedor de alimentos?", "verso": "De 1 a 3 meses, em regime fechado, separado dos presos comuns.", "explicacao": "CPC, art. 528, §§ 3º e 4º."}, {"id": 2000001701, "trilha": "tribunais", "materia": "pciv", "assunto": "Execução", "tipo": "pergunta", "frente": "Cite títulos executivos extrajudiciais.", "verso": "Letra de câmbio, nota promissória, duplicata, cheque, debênture, escritura pública ou documento particular assinado pelo devedor e por 2 testemunhas, contratos com garantia real, entre outros.", "explicacao": "CPC, art. 784."}, {"id": 2000001702, "trilha": "tribunais", "materia": "pciv", "assunto": "Execução", "tipo": "pergunta", "frente": "Qual o prazo para pagar na execução de título extrajudicial?", "verso": "3 dias, contados da citação; se pagar nesse prazo, os honorários caem pela metade.", "explicacao": "CPC, art. 829 e art. 827, § 1º."}, {"id": 2000001703, "trilha": "tribunais", "materia": "pciv", "assunto": "Execução", "tipo": "pergunta", "frente": "Como o executado se defende na execução de título extrajudicial?", "verso": "Por embargos à execução, em 15 dias, independentemente de penhora.", "explicacao": "CPC, arts. 914 e 915."}, {"id": 2000001704, "trilha": "tribunais", "materia": "pciv", "assunto": "Execução", "tipo": "pergunta", "frente": "Os embargos à execução têm efeito suspensivo automático?", "verso": "Não. O juiz pode concedê-lo se presentes os requisitos da tutela provisória e garantido o juízo.", "explicacao": "CPC, art. 919."}, {"id": 2000001705, "trilha": "tribunais", "materia": "pciv", "assunto": "Execução", "tipo": "pergunta", "frente": "O que é o parcelamento do art. 916 do CPC?", "verso": "No prazo dos embargos, o executado deposita 30% da dívida (com custas e honorários) e paga o restante em até 6 parcelas mensais corrigidas, com juros de 1% ao mês.", "explicacao": "Não se aplica ao cumprimento de sentença."}, {"id": 2000001706, "trilha": "tribunais", "materia": "pciv", "assunto": "Execução", "tipo": "pergunta", "frente": "Qual o primeiro bem na ordem preferencial de penhora?", "verso": "Dinheiro, em espécie ou em depósito ou aplicação financeira.", "explicacao": "CPC, art. 835, I."}, {"id": 2000001707, "trilha": "tribunais", "materia": "pciv", "assunto": "Execução", "tipo": "pergunta", "frente": "Cite bens impenhoráveis.", "verso": "Vestuário, salários (com exceções), instrumentos de trabalho, seguro de vida, caderneta de poupança até 40 salários mínimos, pequena propriedade rural trabalhada pela família.", "explicacao": "CPC, art. 833."}, {"id": 2000001708, "trilha": "tribunais", "materia": "pciv", "assunto": "Execução", "tipo": "pergunta", "frente": "O bem de família pode ser penhorado?", "verso": "Em regra, não; há exceções, como dívida de pensão alimentícia, IPTU do próprio imóvel e fiança em locação.", "explicacao": "Lei 8.009/1990, arts. 1º e 3º."}, {"id": 2000001709, "trilha": "tribunais", "materia": "pciv", "assunto": "Execução", "tipo": "pergunta", "frente": "O que é a fraude à execução?", "verso": "Alienação ou oneração de bens quando já tramitava ação capaz de reduzir o devedor à insolvência, entre outras hipóteses; o ato é ineficaz em relação ao exequente.", "explicacao": "CPC, art. 792."}, {"id": 2000001710, "trilha": "tribunais", "materia": "pciv", "assunto": "Procedimentos especiais", "tipo": "pergunta", "frente": "Qual o prazo da ação possessória de força nova?", "verso": "Proposta dentro de ano e dia da turbação ou esbulho, segue o procedimento especial com possibilidade de liminar.", "explicacao": "CPC, art. 558."}, {"id": 2000001711, "trilha": "tribunais", "materia": "pciv", "assunto": "Procedimentos especiais", "tipo": "pergunta", "frente": "O que é ação monitória?", "verso": "Ação de quem tem prova escrita sem eficácia de título executivo para exigir pagamento, entrega de coisa ou obrigação de fazer.", "explicacao": "CPC, art. 700."}, {"id": 2000001712, "trilha": "tribunais", "materia": "pciv", "assunto": "Procedimentos especiais", "tipo": "pergunta", "frente": "Qual o prazo para cumprir o mandado monitório e quais as vantagens?", "verso": "15 dias; se cumprir, fica isento de custas e paga honorários de 5%.", "explicacao": "CPC, art. 701."}, {"id": 2000001713, "trilha": "tribunais", "materia": "pciv", "assunto": "Procedimentos especiais", "tipo": "pergunta", "frente": "Para que servem os embargos de terceiro?", "verso": "Para quem, não sendo parte, sofrer constrição ou ameaça de constrição sobre bens que possua ou sobre os quais tenha direito.", "explicacao": "CPC, art. 674."}, {"id": 2000001714, "trilha": "tribunais", "materia": "pciv", "assunto": "Juizados Especiais", "tipo": "pergunta", "frente": "Qual o limite de valor das causas no Juizado Especial Cível estadual?", "verso": "40 salários mínimos; até 20, a parte pode atuar sem advogado.", "explicacao": "Lei 9.099/1995, arts. 3º e 9º."}, {"id": 2000001715, "trilha": "tribunais", "materia": "pciv", "assunto": "Juizados Especiais", "tipo": "pergunta", "frente": "Qual o limite do Juizado Especial Federal?", "verso": "60 salários mínimos.", "explicacao": "Lei 10.259/2001, art. 3º."}, {"id": 2000001716, "trilha": "tribunais", "materia": "pciv", "assunto": "Juizados Especiais", "tipo": "pergunta", "frente": "Cabe ação rescisória no Juizado Especial Cível?", "verso": "Não.", "explicacao": "Lei 9.099/1995, art. 59."}, {"id": 2000001717, "trilha": "tribunais", "materia": "pciv", "assunto": "Juizados Especiais", "tipo": "pergunta", "frente": "Qual o recurso contra a sentença no Juizado Especial Cível e seu prazo?", "verso": "Recurso inominado, em 10 dias, julgado pela Turma Recursal.", "explicacao": "Lei 9.099/1995, arts. 41 e 42."}, {"id": 2000001718, "trilha": "tribunais", "materia": "pciv", "assunto": "Mandado de segurança", "tipo": "pergunta", "frente": "Qual o prazo para impetrar mandado de segurança?", "verso": "120 dias, contados da ciência do ato impugnado.", "explicacao": "Lei 12.016/2009, art. 23."}, {"id": 2000001719, "trilha": "tribunais", "materia": "pciv", "assunto": "Mandado de segurança", "tipo": "pergunta", "frente": "Há condenação em honorários no mandado de segurança?", "verso": "Não.", "explicacao": "Lei 12.016/2009, art. 25; Súmula 512 do STF."}, {"id": 2000001720, "trilha": "tribunais", "materia": "arq", "assunto": "Conceitos", "tipo": "pergunta", "frente": "Como a Lei 8.159/1991 define arquivos?", "verso": "Conjuntos de documentos produzidos e recebidos por órgãos públicos, instituições de caráter público e entidades privadas, em decorrência de suas atividades, qualquer que seja o suporte ou a natureza dos documentos.", "explicacao": "Lei 8.159/1991, art. 2º."}, {"id": 2000001721, "trilha": "tribunais", "materia": "arq", "assunto": "Conceitos", "tipo": "pares", "frente": "Arquivo x biblioteca x museu.", "verso": "Arquivo: documentos produzidos ou recebidos naturalmente no exercício de atividades, com valor de prova. Biblioteca: material colecionado para fins culturais e de informação, com vários exemplares. Museu: objetos colecionados com finalidade cultural e educativa.", "explicacao": "Arquivo é acumulação natural; biblioteca e museu, coleção."}, {"id": 2000001722, "trilha": "tribunais", "materia": "arq", "assunto": "Conceitos", "tipo": "pares", "frente": "Fundo x coleção.", "verso": "Fundo: conjunto de documentos de uma mesma proveniência, acumulados organicamente. Coleção: reunião artificial de documentos por algum critério (tema, autor).", "explicacao": "O arquivo é formado por fundos."}, {"id": 2000001723, "trilha": "tribunais", "materia": "arq", "assunto": "Conceitos", "tipo": "pergunta", "frente": "O que é documento de arquivo?", "verso": "Informação registrada em um suporte, produzida ou recebida no decurso das atividades de uma instituição ou pessoa, que serve de prova dessas atividades.", "explicacao": ""}, {"id": 2000001724, "trilha": "tribunais", "materia": "arq", "assunto": "Conceitos", "tipo": "pergunta", "frente": "Qual o dever do Poder Público em relação aos documentos de arquivo?", "verso": "A gestão documental e a proteção especial a documentos de arquivos, como instrumento de apoio à administração, à cultura, ao desenvolvimento científico e como elementos de prova e informação.", "explicacao": "Lei 8.159/1991, art. 1º; CF, art. 216, § 2º."}, {"id": 2000001725, "trilha": "tribunais", "materia": "arq", "assunto": "Princípios", "tipo": "pergunta", "frente": "O que diz o princípio da proveniência (respeito aos fundos)?", "verso": "Os documentos de uma mesma origem (entidade produtora) devem ser mantidos juntos, sem se misturar com os de outras origens.", "explicacao": "Princípio basilar da arquivologia."}, {"id": 2000001726, "trilha": "tribunais", "materia": "arq", "assunto": "Princípios", "tipo": "pergunta", "frente": "O que diz o princípio da ordem original?", "verso": "Deve-se manter a ordem dada aos documentos pela entidade que os produziu.", "explicacao": "Também chamado respeito à ordem original."}, {"id": 2000001727, "trilha": "tribunais", "materia": "arq", "assunto": "Princípios", "tipo": "pergunta", "frente": "O que é o princípio da organicidade?", "verso": "Os documentos refletem a estrutura, as funções e as atividades da entidade produtora, mantendo relações entre si.", "explicacao": ""}, {"id": 2000001728, "trilha": "tribunais", "materia": "arq", "assunto": "Princípios", "tipo": "pergunta", "frente": "O que é o princípio da indivisibilidade (integridade)?", "verso": "Os fundos devem ser preservados sem dispersão, mutilação, alienação ou acréscimos indevidos.", "explicacao": ""}, {"id": 2000001729, "trilha": "tribunais", "materia": "arq", "assunto": "Princípios", "tipo": "pergunta", "frente": "O que é o princípio da cumulatividade (naturalidade)?", "verso": "Os documentos se acumulam de forma natural e progressiva, conforme as atividades são realizadas, e não por coleção.", "explicacao": ""}, {"id": 2000001730, "trilha": "tribunais", "materia": "arq", "assunto": "Princípios", "tipo": "pergunta", "frente": "O que é a unicidade do documento de arquivo?", "verso": "Cada documento tem caráter único no conjunto a que pertence, por seu contexto de produção, mesmo que existam cópias.", "explicacao": ""}, {"id": 2000001731, "trilha": "tribunais", "materia": "arq", "assunto": "Princípios", "tipo": "pergunta", "frente": "O que é o princípio da territorialidade?", "verso": "Os arquivos devem ser conservados no território em que foram produzidos.", "explicacao": "Também chamado de pertinência territorial."}, {"id": 2000001732, "trilha": "tribunais", "materia": "arq", "assunto": "Ciclo vital", "tipo": "pergunta", "frente": "Quais as três idades dos arquivos?", "verso": "Corrente (1ª), intermediária (2ª) e permanente (3ª).", "explicacao": "Teoria das três idades. Lei 8.159/1991, art. 8º."}, {"id": 2000001733, "trilha": "tribunais", "materia": "arq", "assunto": "Ciclo vital", "tipo": "pergunta", "frente": "O que é arquivo corrente?", "verso": "Conjunto de documentos em curso ou que, mesmo sem movimentação, são objeto de consultas frequentes.", "explicacao": "Lei 8.159/1991, art. 8º, § 1º."}, {"id": 2000001734, "trilha": "tribunais", "materia": "arq", "assunto": "Ciclo vital", "tipo": "pergunta", "frente": "O que é arquivo intermediário?", "verso": "Documentos que, não sendo de uso corrente nos órgãos produtores, por razões de interesse administrativo aguardam a eliminação ou o recolhimento para guarda permanente.", "explicacao": "Lei 8.159/1991, art. 8º, § 2º."}, {"id": 2000001735, "trilha": "tribunais", "materia": "arq", "assunto": "Ciclo vital", "tipo": "pergunta", "frente": "O que é arquivo permanente?", "verso": "Conjunto de documentos de valor histórico, probatório e informativo que devem ser definitivamente preservados.", "explicacao": "Lei 8.159/1991, art. 8º, § 3º."}, {"id": 2000001736, "trilha": "tribunais", "materia": "arq", "assunto": "Ciclo vital", "tipo": "certo_errado", "frente": "Certo ou errado? Os documentos de valor permanente podem ser eliminados após microfilmagem.", "verso": "Errado. São inalienáveis e imprescritíveis e não podem ser eliminados, mesmo microfilmados.", "explicacao": "Lei 8.159/1991, art. 10."}, {"id": 2000001737, "trilha": "tribunais", "materia": "arq", "assunto": "Ciclo vital", "tipo": "pares", "frente": "Transferência x recolhimento.", "verso": "Transferência: passagem do arquivo corrente para o intermediário. Recolhimento: entrada de documentos no arquivo permanente.", "explicacao": "Pegadinha clássica."}, {"id": 2000001738, "trilha": "tribunais", "materia": "arq", "assunto": "Ciclo vital", "tipo": "pares", "frente": "Valor primário x secundário.", "verso": "Primário: interesse para a entidade produtora, ligado à razão de sua criação (administrativo, legal, fiscal). Secundário: interesse para outros fins, como pesquisa e história (probatório e informativo).", "explicacao": "O valor secundário leva à guarda permanente."}, {"id": 2000001739, "trilha": "tribunais", "materia": "arq", "assunto": "Gestão documental", "tipo": "pergunta", "frente": "Como a Lei 8.159 define gestão de documentos?", "verso": "Conjunto de procedimentos e operações técnicas referentes à produção, tramitação, uso, avaliação e arquivamento de documentos nas fases corrente e intermediária, visando à eliminação ou ao recolhimento para guarda permanente.", "explicacao": "Lei 8.159/1991, art. 3º."}, {"id": 2000001740, "trilha": "tribunais", "materia": "arq", "assunto": "Gestão documental", "tipo": "pergunta", "frente": "Quais as três fases básicas da gestão de documentos?", "verso": "Produção, utilização (manutenção e uso) e destinação.", "explicacao": ""}, {"id": 2000001741, "trilha": "tribunais", "materia": "arq", "assunto": "Gestão documental", "tipo": "pergunta", "frente": "O que é avaliação de documentos?", "verso": "Processo de análise que estabelece os prazos de guarda e a destinação dos documentos (eliminação ou guarda permanente), conforme seus valores.", "explicacao": "Realizada por comissão permanente de avaliação."}, {"id": 2000001742, "trilha": "tribunais", "materia": "arq", "assunto": "Gestão documental", "tipo": "pergunta", "frente": "O que é a tabela de temporalidade?", "verso": "Instrumento que define os prazos de guarda nas fases corrente e intermediária e a destinação final (eliminação ou guarda permanente) dos documentos.", "explicacao": "Aprovada por autoridade competente."}, {"id": 2000001743, "trilha": "tribunais", "materia": "arq", "assunto": "Gestão documental", "tipo": "pergunta", "frente": "Para que serve o plano de classificação?", "verso": "Esquema que distribui os documentos em classes, conforme as funções e atividades do órgão, orientando seu arquivamento e recuperação.", "explicacao": "No Conarq, código de classificação de atividades-meio."}, {"id": 2000001744, "trilha": "tribunais", "materia": "arq", "assunto": "Gestão documental", "tipo": "pares", "frente": "Atividade-meio x atividade-fim.", "verso": "Atividade-meio: apoio ao funcionamento do órgão (pessoal, material, patrimônio, orçamento). Atividade-fim: a missão específica do órgão.", "explicacao": "O código do Conarq trata das atividades-meio."}, {"id": 2000001745, "trilha": "tribunais", "materia": "arq", "assunto": "Gestão documental", "tipo": "pergunta", "frente": "A eliminação de documentos públicos pode ser feita livremente pelo órgão?", "verso": "Não. Depende de autorização da instituição arquivística pública em sua esfera de competência.", "explicacao": "Lei 8.159/1991, art. 9º."}, {"id": 2000001746, "trilha": "tribunais", "materia": "arq", "assunto": "Gestão documental", "tipo": "pergunta", "frente": "Que instrumento formaliza a eliminação de documentos?", "verso": "Listagem de eliminação, edital de ciência de eliminação e termo de eliminação.", "explicacao": "Resolução Conarq."}, {"id": 2000001747, "trilha": "tribunais", "materia": "arq", "assunto": "Gestão documental", "tipo": "pergunta", "frente": "O que é o protocolo na gestão documental?", "verso": "Setor ou atividade de recebimento, registro, classificação, distribuição, controle da tramitação e expedição de documentos.", "explicacao": ""}, {"id": 2000001748, "trilha": "tribunais", "materia": "arq", "assunto": "Gestão documental", "tipo": "pares", "frente": "Autuação x juntada.", "verso": "Autuação: transformar documento em processo (com capa, número e folhas numeradas). Juntada: união de documento ou processo a outro processo, por anexação ou apensação.", "explicacao": ""}, {"id": 2000001749, "trilha": "tribunais", "materia": "arq", "assunto": "Gestão documental", "tipo": "pares", "frente": "Anexação x apensação.", "verso": "Anexação: união definitiva, prevalecendo o número do processo principal. Apensação: união temporária, para estudo conjunto, e cada processo mantém sua identidade.", "explicacao": ""}, {"id": 2000001750, "trilha": "tribunais", "materia": "arq", "assunto": "Classificação", "tipo": "pares", "frente": "Documento ostensivo x sigiloso.", "verso": "Ostensivo: acesso livre ao público. Sigiloso: acesso restrito, por imprescindível à segurança da sociedade e do Estado ou por dizer respeito à intimidade.", "explicacao": ""}, {"id": 2000001751, "trilha": "tribunais", "materia": "arq", "assunto": "Classificação", "tipo": "pergunta", "frente": "Quais os graus de sigilo da Lei de Acesso à Informação e os prazos?", "verso": "Ultrassecreta: 25 anos; secreta: 15 anos; reservada: 5 anos.", "explicacao": "Lei 12.527/2011, art. 24."}, {"id": 2000001752, "trilha": "tribunais", "materia": "arq", "assunto": "Classificação", "tipo": "pergunta", "frente": "Por quanto tempo informações pessoais relativas à intimidade têm acesso restrito?", "verso": "Pelo prazo máximo de 100 anos a contar da data de produção.", "explicacao": "Lei 12.527/2011, art. 31."}, {"id": 2000001753, "trilha": "tribunais", "materia": "arq", "assunto": "Classificação", "tipo": "pergunta", "frente": "O prazo de sigilo ultrassecreto pode ser prorrogado?", "verso": "Sim, uma única vez, por até 25 anos, pela Comissão Mista de Reavaliação de Informações.", "explicacao": "Lei 12.527/2011, art. 35, § 1º, III."}, {"id": 2000001754, "trilha": "tribunais", "materia": "arq", "assunto": "Arranjo e descrição", "tipo": "pergunta", "frente": "O que é arranjo?", "verso": "Organização dos documentos de um arquivo permanente, conforme os princípios arquivísticos.", "explicacao": "No arquivo corrente fala-se em classificação."}, {"id": 2000001755, "trilha": "tribunais", "materia": "arq", "assunto": "Arranjo e descrição", "tipo": "pergunta", "frente": "O que é descrição arquivística?", "verso": "Elaboração de instrumentos de pesquisa que identificam, localizam e explicam o conteúdo dos documentos do arquivo permanente.", "explicacao": "Norma brasileira: NOBRADE."}, {"id": 2000001756, "trilha": "tribunais", "materia": "arq", "assunto": "Arranjo e descrição", "tipo": "pergunta", "frente": "Quais são os instrumentos de pesquisa?", "verso": "Guia, inventário, catálogo e repertório (e índices).", "explicacao": ""}, {"id": 2000001757, "trilha": "tribunais", "materia": "arq", "assunto": "Arranjo e descrição", "tipo": "pares", "frente": "Guia x inventário x catálogo.", "verso": "Guia: visão geral de todo o acervo da instituição. Inventário: descreve conjuntos (fundos, séries) de modo sumário. Catálogo: descreve documentos um a um, de forma pormenorizada.", "explicacao": "Repertório: descreve documentos selecionados de um ou mais fundos."}, {"id": 2000001758, "trilha": "tribunais", "materia": "arq", "assunto": "Arranjo e descrição", "tipo": "pergunta", "frente": "Quantos níveis de descrição prevê a NOBRADE?", "verso": "Seis níveis principais: acervo da entidade custodiadora (0), fundo ou coleção (1), seção (2), série (3), dossiê ou processo (4) e item documental (5).", "explicacao": "Admite níveis intermediários (subseção, subsérie)."}, {"id": 2000001759, "trilha": "tribunais", "materia": "arq", "assunto": "Arranjo e descrição", "tipo": "pergunta", "frente": "Quantos elementos de descrição têm a NOBRADE e quais são obrigatórios?", "verso": "28 elementos; 7 obrigatórios: código de referência, título, data, nível de descrição, dimensão e suporte, nome do produtor e condições de acesso.", "explicacao": "Inspirada na ISAD(G)."}, {"id": 2000001760, "trilha": "tribunais", "materia": "arq", "assunto": "Arranjo e descrição", "tipo": "pergunta", "frente": "O que é a ISAD(G)?", "verso": "Norma geral internacional de descrição arquivística, do Conselho Internacional de Arquivos.", "explicacao": "A NOBRADE é sua adaptação brasileira."}, {"id": 2000001761, "trilha": "tribunais", "materia": "arq", "assunto": "Métodos de arquivamento", "tipo": "pares", "frente": "Métodos básicos x padronizados.", "verso": "Básicos: alfabético, geográfico, numérico (simples, cronológico, dígito-terminal) e ideográfico (por assunto). Padronizados: variadex, automático, soundex, mnemônico e rôneo.", "explicacao": ""}, {"id": 2000001762, "trilha": "tribunais", "materia": "arq", "assunto": "Métodos de arquivamento", "tipo": "pares", "frente": "Método direto x indireto.", "verso": "Direto: busca-se o documento diretamente, sem consultar índice (alfabético, geográfico). Indireto: exige consultar um índice antes (numérico).", "explicacao": ""}, {"id": 2000001763, "trilha": "tribunais", "materia": "arq", "assunto": "Métodos de arquivamento", "tipo": "pergunta", "frente": "O método alfabético é direto ou indireto?", "verso": "Direto.", "explicacao": "É o mais simples e rápido, mas sujeito a erros quando há muitos documentos."}, {"id": 2000001764, "trilha": "tribunais", "materia": "arq", "assunto": "Métodos de arquivamento", "tipo": "pergunta", "frente": "Pela regra de alfabetação, como se arquiva o nome “José Carlos Almeida”?", "verso": "Pelo último sobrenome: Almeida, José Carlos.", "explicacao": "Regra 1 da alfabetação."}, {"id": 2000001765, "trilha": "tribunais", "materia": "arq", "assunto": "Métodos de arquivamento", "tipo": "pergunta", "frente": "Como se arquivam sobrenomes com Filho, Júnior, Neto e Sobrinho?", "verso": "Esses termos acompanham o último sobrenome: “Oliveira Neto, Antônio”.", "explicacao": ""}, {"id": 2000001766, "trilha": "tribunais", "materia": "arq", "assunto": "Métodos de arquivamento", "tipo": "pergunta", "frente": "Como se arquivam sobrenomes compostos de substantivo e adjetivo ou ligados por hífen?", "verso": "Não se separam: “Castelo Branco, Carlos”; “Villa-Lobos, Heitor”.", "explicacao": ""}, {"id": 2000001767, "trilha": "tribunais", "materia": "arq", "assunto": "Métodos de arquivamento", "tipo": "pergunta", "frente": "Como se arquivam sobrenomes formados com “Santa”, “Santo” ou “São”?", "verso": "Não se separam: “Santa Rita, Walter”; “São Paulo, Pedro”.", "explicacao": ""}, {"id": 2000001768, "trilha": "tribunais", "materia": "arq", "assunto": "Métodos de arquivamento", "tipo": "pergunta", "frente": "Como se arquivam nomes orientais (japoneses, chineses e árabes)?", "verso": "Como se apresentam, sem inversão: “Li Yutang”.", "explicacao": ""}, {"id": 2000001769, "trilha": "tribunais", "materia": "arq", "assunto": "Métodos de arquivamento", "tipo": "pergunta", "frente": "Como se arquivam títulos como doutor, professor e general?", "verso": "Não são considerados na alfabetação; vêm entre parênteses no final: “Pereira, Paulo (Doutor)”.", "explicacao": ""}, {"id": 2000001770, "trilha": "tribunais", "materia": "arq", "assunto": "Métodos de arquivamento", "tipo": "pergunta", "frente": "Como se arquivam artigos e preposições como “a”, “de”, “da”, “do”?", "verso": "Não são considerados na alfabetação.", "explicacao": "Exceção para sobrenomes estrangeiros com partículas como “D'” e “O'”."}, {"id": 2000001771, "trilha": "tribunais", "materia": "arq", "assunto": "Métodos de arquivamento", "tipo": "pergunta", "frente": "Em que ordem se arquiva pelo método geográfico?", "verso": "Por local: em regra, estado, cidade e correspondente; as capitais vêm antes das demais cidades do estado.", "explicacao": ""}, {"id": 2000001772, "trilha": "tribunais", "materia": "arq", "assunto": "Métodos de arquivamento", "tipo": "pergunta", "frente": "O que é o método dígito-terminal?", "verso": "Método numérico em que os números são lidos em grupos de dois dígitos da direita para a esquerda, reduzindo erros em grandes volumes.", "explicacao": "Usado em hospitais e grandes fichários."}, {"id": 2000001773, "trilha": "tribunais", "materia": "arq", "assunto": "Métodos de arquivamento", "tipo": "pergunta", "frente": "O que é o método variadex?", "verso": "Método alfabético que atribui cores diferentes às letras, de acordo com a segunda letra do nome.", "explicacao": "Facilita a localização visual."}, {"id": 2000001774, "trilha": "tribunais", "materia": "arq", "assunto": "Métodos de arquivamento", "tipo": "pares", "frente": "Arquivamento ideográfico alfabético x numérico.", "verso": "Alfabético: assuntos em ordem alfabética (dicionário ou enciclopédia). Numérico: assuntos codificados com números (duplex, decimal, unitermo).", "explicacao": "O método decimal usa a classificação de Dewey."}, {"id": 2000001775, "trilha": "tribunais", "materia": "arq", "assunto": "Conservação", "tipo": "pergunta", "frente": "Quais os principais agentes de deterioração do papel?", "verso": "Físicos (luz, temperatura, umidade), químicos (acidez, poluição), biológicos (fungos, insetos, roedores) e humanos (manuseio inadequado, desastres).", "explicacao": ""}, {"id": 2000001776, "trilha": "tribunais", "materia": "arq", "assunto": "Conservação", "tipo": "pergunta", "frente": "Quais as condições ambientais recomendadas para acervos em papel?", "verso": "Temperatura em torno de 20 °C e umidade relativa entre 45% e 55%, com pouca oscilação.", "explicacao": "Recomendações do Conarq."}, {"id": 2000001777, "trilha": "tribunais", "materia": "arq", "assunto": "Conservação", "tipo": "pares", "frente": "Conservação x restauração.", "verso": "Conservação: ações preventivas para retardar a deterioração (controle ambiental, acondicionamento). Restauração: intervenção para recuperar documento já danificado.", "explicacao": ""}, {"id": 2000001778, "trilha": "tribunais", "materia": "arq", "assunto": "Conservação", "tipo": "pergunta", "frente": "Por que se removem clipes e grampos metálicos dos documentos?", "verso": "Porque oxidam e mancham ou rasgam o papel.", "explicacao": "Substituídos por clipes de plástico ou material inerte."}, {"id": 2000001779, "trilha": "tribunais", "materia": "arq", "assunto": "Conservação", "tipo": "pergunta", "frente": "O que é higienização de documentos?", "verso": "Remoção de poeira, sujidades e elementos agressivos (grampos, fitas adesivas) dos documentos.", "explicacao": "Primeira etapa da conservação."}, {"id": 2000001780, "trilha": "tribunais", "materia": "arq", "assunto": "Conservação", "tipo": "pergunta", "frente": "O que é a laminação e por que é desaconselhada?", "verso": "Selagem do documento entre películas plásticas com calor; é difícil de reverter e pode acelerar danos.", "explicacao": "Na conservação, preferem-se intervenções reversíveis."}, {"id": 2000001781, "trilha": "tribunais", "materia": "arq", "assunto": "Reprodução", "tipo": "pergunta", "frente": "Qual a vida útil estimada de um microfilme bem processado e guardado?", "verso": "Pode chegar a 500 anos.", "explicacao": "Microfilme é suporte de preservação de longo prazo."}, {"id": 2000001782, "trilha": "tribunais", "materia": "arq", "assunto": "Reprodução", "tipo": "pergunta", "frente": "O que é digitalização?", "verso": "Conversão de documento em suporte físico para formato digital, por meio de dispositivo como o scanner.", "explicacao": "Gera um representante digital, não substitui o original permanente."}, {"id": 2000001783, "trilha": "tribunais", "materia": "arq", "assunto": "Documentos digitais", "tipo": "pares", "frente": "Documento digital x eletrônico.", "verso": "Eletrônico: acessível e interpretável por equipamento eletrônico (fita de vídeo, disquete). Digital: codificado em dígitos binários, acessível por sistema computacional.", "explicacao": "Todo digital é eletrônico, mas nem todo eletrônico é digital."}, {"id": 2000001784, "trilha": "tribunais", "materia": "arq", "assunto": "Documentos digitais", "tipo": "pergunta", "frente": "O que é o e-ARQ Brasil?", "verso": "Modelo de requisitos para sistemas informatizados de gestão arquivística de documentos (SIGAD).", "explicacao": "Aprovado pelo Conarq."}, {"id": 2000001785, "trilha": "tribunais", "materia": "arq", "assunto": "Documentos digitais", "tipo": "pergunta", "frente": "O que é um RDC-Arq?", "verso": "Repositório arquivístico digital confiável: ambiente que garante a preservação e o acesso de longo prazo a documentos digitais autênticos.", "explicacao": "Diretrizes do Conarq."}, {"id": 2000001786, "trilha": "tribunais", "materia": "arq", "assunto": "Documentos digitais", "tipo": "pergunta", "frente": "O que é autenticidade do documento arquivístico?", "verso": "A qualidade de ser o que diz ser, livre de adulteração; envolve identidade e integridade.", "explicacao": ""}, {"id": 2000001787, "trilha": "tribunais", "materia": "arq", "assunto": "Legislação", "tipo": "pergunta", "frente": "O que é o Conarq?", "verso": "Conselho Nacional de Arquivos, órgão vinculado ao Arquivo Nacional que define a política nacional de arquivos públicos e privados.", "explicacao": "Lei 8.159/1991, art. 26."}, {"id": 2000001788, "trilha": "tribunais", "materia": "arq", "assunto": "Legislação", "tipo": "pergunta", "frente": "O que é o SINAR?", "verso": "Sistema Nacional de Arquivos, que tem o Conarq como órgão central.", "explicacao": "Decreto 4.073/2002."}, {"id": 2000001789, "trilha": "tribunais", "materia": "arq", "assunto": "Legislação", "tipo": "pergunta", "frente": "Quem é responsável pela gestão e recolhimento dos documentos do Poder Executivo Federal?", "verso": "O Arquivo Nacional.", "explicacao": "Lei 8.159/1991, art. 18."}, {"id": 2000001790, "trilha": "tribunais", "materia": "arq", "assunto": "Legislação", "tipo": "pergunta", "frente": "A quem compete a gestão dos documentos do Poder Judiciário Federal?", "verso": "Aos arquivos do próprio Poder Judiciário Federal.", "explicacao": "Lei 8.159/1991, art. 20."}, {"id": 2000001791, "trilha": "tribunais", "materia": "arq", "assunto": "Legislação", "tipo": "pergunta", "frente": "Arquivos privados podem ser declarados de interesse público e social?", "verso": "Sim, quando contiverem documentos relevantes para a história, a cultura e o desenvolvimento nacional; não podem ser alienados com dispersão ou ser transferidos para o exterior.", "explicacao": "Lei 8.159/1991, arts. 12 e 13."}, {"id": 2000001792, "trilha": "tribunais", "materia": "arq", "assunto": "Legislação", "tipo": "pergunta", "frente": "Qual a pena para quem destruir documentos de valor permanente ou considerados de interesse público e social?", "verso": "Responsabilidade penal, civil e administrativa, na forma da legislação.", "explicacao": "Lei 8.159/1991, art. 25."}, {"id": 2000001793, "trilha": "tribunais", "materia": "arq", "assunto": "Legislação", "tipo": "pergunta", "frente": "Qual a lei que trata da digitalização de documentos e do descarte do original?", "verso": "Lei 12.682/2012 (com mudanças da Lei 13.874/2019), que dá ao documento digitalizado conforme os requisitos o mesmo valor probatório do original.", "explicacao": "Documentos de valor histórico devem ser preservados."}, {"id": 2000001794, "trilha": "tribunais", "materia": "arq", "assunto": "Judiciário", "tipo": "pergunta", "frente": "Qual o programa do CNJ para a gestão documental do Poder Judiciário?", "verso": "O Proname (Programa Nacional de Gestão Documental e Memória do Poder Judiciário).", "explicacao": "Resolução CNJ 324/2020."}, {"id": 2000001795, "trilha": "tribunais", "materia": "arq", "assunto": "Judiciário", "tipo": "pergunta", "frente": "O que são documentos de guarda permanente no Judiciário?", "verso": "Processos e documentos de valor histórico, probatório e informativo, definidos pela tabela de temporalidade e por amostragem estatística.", "explicacao": "Proname."}, {"id": 2000001796, "trilha": "tribunais", "materia": "arq", "assunto": "Tipologia", "tipo": "pares", "frente": "Espécie x tipo documental.", "verso": "Espécie: formato do documento conforme a disposição das informações (ofício, ata, certidão). Tipo: espécie somada à atividade que a gerou (certidão de nascimento, ata de reunião).", "explicacao": "Diplomática e tipologia documental."}, {"id": 2000001797, "trilha": "tribunais", "materia": "arq", "assunto": "Tipologia", "tipo": "pares", "frente": "Gênero documental: textual x iconográfico x cartográfico.", "verso": "Textual: escrito (atas, ofícios). Iconográfico: imagens fixas (fotos, desenhos). Cartográfico: representações gráficas de áreas (mapas, plantas).", "explicacao": "Outros: filmográfico, sonoro, micrográfico, informático."}, {"id": 2000001798, "trilha": "tribunais", "materia": "arq", "assunto": "Tipologia", "tipo": "pergunta", "frente": "O que é documento de caráter sigiloso pela natureza do assunto?", "verso": "Aquele cujo conhecimento irrestrito pode trazer risco à segurança da sociedade e do Estado ou violar a intimidade.", "explicacao": ""}, {"id": 2000001799, "trilha": "tribunais", "materia": "arq", "assunto": "Tipologia", "tipo": "pares", "frente": "Original x cópia x minuta.", "verso": "Original: primeiro documento completo e efetivo. Cópia: reprodução do original. Minuta: versão preliminar, sujeita a alterações.", "explicacao": ""}, {"id": 2000001800, "trilha": "tribunais", "materia": "prev", "assunto": "Seguridade social", "tipo": "pergunta", "frente": "Quais as três áreas da seguridade social?", "verso": "Saúde, previdência social e assistência social.", "explicacao": "CF, art. 194."}, {"id": 2000001801, "trilha": "tribunais", "materia": "prev", "assunto": "Seguridade social", "tipo": "pares", "frente": "Saúde x previdência x assistência social.", "verso": "Saúde: direito de todos, independe de contribuição. Previdência: caráter contributivo e filiação obrigatória. Assistência: a quem dela necessitar, independe de contribuição.", "explicacao": "CF, arts. 196, 201 e 203."}, {"id": 2000001802, "trilha": "tribunais", "materia": "prev", "assunto": "Seguridade social", "tipo": "pergunta", "frente": "Cite objetivos (princípios) da seguridade social.", "verso": "Universalidade da cobertura e do atendimento; uniformidade e equivalência entre populações urbanas e rurais; seletividade e distributividade; irredutibilidade do valor dos benefícios; equidade no custeio; diversidade da base de financiamento; gestão quadripartite.", "explicacao": "CF, art. 194, parágrafo único."}, {"id": 2000001803, "trilha": "tribunais", "materia": "prev", "assunto": "Seguridade social", "tipo": "pergunta", "frente": "Quem compõe a gestão quadripartite da seguridade social?", "verso": "Trabalhadores, empregadores, aposentados e Governo.", "explicacao": "CF, art. 194, parágrafo único, VII."}, {"id": 2000001804, "trilha": "tribunais", "materia": "prev", "assunto": "Seguridade social", "tipo": "pergunta", "frente": "O que é a regra da contrapartida (precedência do custeio)?", "verso": "Nenhum benefício ou serviço da seguridade pode ser criado, majorado ou estendido sem a correspondente fonte de custeio total.", "explicacao": "CF, art. 195, § 5º."}, {"id": 2000001805, "trilha": "tribunais", "materia": "prev", "assunto": "Seguridade social", "tipo": "pergunta", "frente": "Qual a anterioridade das contribuições sociais para a seguridade?", "verso": "Noventena: só podem ser exigidas 90 dias após a publicação da lei que as instituiu ou modificou.", "explicacao": "CF, art. 195, § 6º. Não se aplica a anterioridade de exercício."}, {"id": 2000001806, "trilha": "tribunais", "materia": "prev", "assunto": "Custeio", "tipo": "pergunta", "frente": "Quais as fontes de financiamento da seguridade social?", "verso": "Toda a sociedade, de forma direta e indireta: recursos dos orçamentos públicos e contribuições sociais do empregador, do trabalhador, sobre a receita de concursos de prognósticos e do importador.", "explicacao": "CF, art. 195."}, {"id": 2000001807, "trilha": "tribunais", "materia": "prev", "assunto": "Custeio", "tipo": "pergunta", "frente": "Qual a alíquota básica da contribuição patronal sobre a folha?", "verso": "20% sobre o total das remunerações pagas aos segurados empregados e trabalhadores avulsos.", "explicacao": "Lei 8.212/1991, art. 22, I."}, {"id": 2000001808, "trilha": "tribunais", "materia": "prev", "assunto": "Custeio", "tipo": "pergunta", "frente": "Quais as alíquotas progressivas do segurado empregado após a EC 103/2019?", "verso": "7,5%, 9%, 12% e 14%, aplicadas por faixas de salário de contribuição.", "explicacao": "EC 103/2019, art. 28."}, {"id": 2000001809, "trilha": "tribunais", "materia": "prev", "assunto": "Custeio", "tipo": "pergunta", "frente": "Qual a alíquota do contribuinte individual que presta serviço a pessoa física ou por conta própria?", "verso": "20% sobre o salário de contribuição.", "explicacao": "Lei 8.212/1991, art. 21. Há plano simplificado de 11% e MEI de 5%."}, {"id": 2000001810, "trilha": "tribunais", "materia": "prev", "assunto": "Custeio", "tipo": "pergunta", "frente": "Qual o prazo decadencial para a Receita constituir créditos de contribuições previdenciárias?", "verso": "5 anos.", "explicacao": "Súmula Vinculante 8 do STF, que declarou inconstitucionais os prazos de 10 anos da Lei 8.212."}, {"id": 2000001811, "trilha": "tribunais", "materia": "prev", "assunto": "Segurados", "tipo": "pares", "frente": "Segurado obrigatório x facultativo.", "verso": "Obrigatório: exerce atividade remunerada (filiação automática). Facultativo: maior de 16 anos sem atividade que o vincule obrigatoriamente, que se filia por vontade própria (dona de casa, estudante).", "explicacao": "Lei 8.213/1991, arts. 11 e 13."}, {"id": 2000001812, "trilha": "tribunais", "materia": "prev", "assunto": "Segurados", "tipo": "pergunta", "frente": "Quais são os segurados obrigatórios do RGPS?", "verso": "Empregado, empregado doméstico, contribuinte individual, trabalhador avulso e segurado especial.", "explicacao": "Lei 8.213/1991, art. 11."}, {"id": 2000001813, "trilha": "tribunais", "materia": "prev", "assunto": "Segurados", "tipo": "pergunta", "frente": "Quem é o segurado especial?", "verso": "Produtor rural, pescador artesanal e assemelhados que trabalham individualmente ou em regime de economia familiar, além de cônjuge e filhos maiores de 16 anos que trabalhem com o grupo.", "explicacao": "Lei 8.213/1991, art. 11, VII."}, {"id": 2000001814, "trilha": "tribunais", "materia": "prev", "assunto": "Segurados", "tipo": "pergunta", "frente": "Qual a idade mínima para filiação ao RGPS?", "verso": "16 anos, salvo o menor aprendiz, a partir de 14.", "explicacao": "CF, art. 7º, XXXIII."}, {"id": 2000001815, "trilha": "tribunais", "materia": "prev", "assunto": "Segurados", "tipo": "pergunta", "frente": "Quem é o trabalhador avulso?", "verso": "Quem presta serviço a diversas empresas, sem vínculo de emprego, com intermediação obrigatória do órgão gestor de mão de obra ou do sindicato.", "explicacao": "Ex.: estivador. Lei 8.213/1991, art. 11, VI."}, {"id": 2000001816, "trilha": "tribunais", "materia": "prev", "assunto": "Segurados", "tipo": "pergunta", "frente": "O servidor público ocupante de cargo efetivo com regime próprio pode se filiar como facultativo no RGPS?", "verso": "Não.", "explicacao": "CF, art. 201, § 5º."}, {"id": 2000001817, "trilha": "tribunais", "materia": "prev", "assunto": "Qualidade de segurado", "tipo": "pergunta", "frente": "O que é o período de graça?", "verso": "Período em que a pessoa mantém a qualidade de segurado mesmo sem contribuir.", "explicacao": "Lei 8.213/1991, art. 15."}, {"id": 2000001818, "trilha": "tribunais", "materia": "prev", "assunto": "Qualidade de segurado", "tipo": "pergunta", "frente": "Qual o período de graça do segurado que deixa de exercer atividade remunerada?", "verso": "Até 12 meses após a cessação das contribuições; prorrogável para 24 se tiver mais de 120 contribuições sem perda da qualidade, e acrescido de 12 meses se desempregado comprovado.", "explicacao": "Lei 8.213/1991, art. 15, II, §§ 1º e 2º."}, {"id": 2000001819, "trilha": "tribunais", "materia": "prev", "assunto": "Qualidade de segurado", "tipo": "pergunta", "frente": "Qual o período de graça do segurado facultativo?", "verso": "Até 6 meses após a cessação das contribuições.", "explicacao": "Lei 8.213/1991, art. 15, VI."}, {"id": 2000001820, "trilha": "tribunais", "materia": "prev", "assunto": "Qualidade de segurado", "tipo": "pergunta", "frente": "Qual o período de graça de quem está em gozo de benefício?", "verso": "Sem limite de prazo, enquanto estiver recebendo, exceto auxílio-acidente.", "explicacao": "Lei 8.213/1991, art. 15, I."}, {"id": 2000001821, "trilha": "tribunais", "materia": "prev", "assunto": "Carência", "tipo": "pergunta", "frente": "O que é carência?", "verso": "Número mínimo de contribuições mensais indispensáveis para que o beneficiário tenha direito ao benefício.", "explicacao": "Lei 8.213/1991, art. 24."}, {"id": 2000001822, "trilha": "tribunais", "materia": "prev", "assunto": "Carência", "tipo": "pergunta", "frente": "Qual a carência do auxílio por incapacidade temporária e da aposentadoria por incapacidade permanente?", "verso": "12 contribuições mensais.", "explicacao": "Lei 8.213/1991, art. 25, I."}, {"id": 2000001823, "trilha": "tribunais", "materia": "prev", "assunto": "Carência", "tipo": "pergunta", "frente": "Qual a carência do salário-maternidade para contribuinte individual, segurada especial e facultativa?", "verso": "A Lei 8.213 prevê 10 contribuições mensais, mas em 2024 o STF (ADI 2.110) declarou inconstitucional essa exigência de carência.", "explicacao": "Lei 8.213/1991, art. 25, III; STF, ADI 2.110."}, {"id": 2000001824, "trilha": "tribunais", "materia": "prev", "assunto": "Carência", "tipo": "pergunta", "frente": "Qual a carência da aposentadoria por idade e por tempo de contribuição?", "verso": "180 contribuições mensais.", "explicacao": "Lei 8.213/1991, art. 25, II."}, {"id": 2000001825, "trilha": "tribunais", "materia": "prev", "assunto": "Carência", "tipo": "pergunta", "frente": "Quais benefícios independem de carência?", "verso": "Pensão por morte, salário-família, auxílio-acidente e os benefícios por incapacidade decorrentes de acidente de qualquer natureza ou de doença grave da lista oficial, entre outros.", "explicacao": "Lei 8.213/1991, art. 26. O auxílio-reclusão passou a exigir 24 contribuições em 2019."}, {"id": 2000001826, "trilha": "tribunais", "materia": "prev", "assunto": "Carência", "tipo": "pergunta", "frente": "Qual a carência do auxílio-reclusão?", "verso": "24 contribuições mensais.", "explicacao": "Lei 8.213/1991, art. 25, IV, incluído pela Lei 13.846/2019."}, {"id": 2000001827, "trilha": "tribunais", "materia": "prev", "assunto": "Carência", "tipo": "pergunta", "frente": "O que acontece com a carência ao perder a qualidade de segurado?", "verso": "Para os benefícios por incapacidade, salário-maternidade e auxílio-reclusão, o segurado precisa cumprir metade da carência após a nova filiação.", "explicacao": "Lei 8.213/1991, art. 27-A."}, {"id": 2000001828, "trilha": "tribunais", "materia": "prev", "assunto": "Aposentadorias", "tipo": "pergunta", "frente": "Quais os requisitos da aposentadoria programada (regra permanente da EC 103) no RGPS?", "verso": "Homem: 65 anos e 20 de contribuição. Mulher: 62 anos e 15 de contribuição.", "explicacao": "EC 103/2019, art. 19. Homem filiado antes da EC: 15 anos de contribuição."}, {"id": 2000001829, "trilha": "tribunais", "materia": "prev", "assunto": "Aposentadorias", "tipo": "pergunta", "frente": "Como se calcula a aposentadoria programada após a EC 103?", "verso": "60% da média de todos os salários de contribuição, mais 2% por ano que exceder 20 anos de contribuição (homem) ou 15 anos (mulher).", "explicacao": "EC 103/2019, art. 26."}, {"id": 2000001830, "trilha": "tribunais", "materia": "prev", "assunto": "Aposentadorias", "tipo": "pergunta", "frente": "Quais os requisitos da aposentadoria por idade do trabalhador rural?", "verso": "Homem: 60 anos. Mulher: 55 anos. Com 15 anos de atividade rural.", "explicacao": "CF, art. 201, § 7º, II."}, {"id": 2000001831, "trilha": "tribunais", "materia": "prev", "assunto": "Aposentadorias", "tipo": "pergunta", "frente": "A aposentadoria por tempo de contribuição ainda existe?", "verso": "Não para quem se filiou após a EC 103/2019; existem regras de transição para quem já era filiado.", "explicacao": "Transições: pontos, idade mínima progressiva, pedágio de 50% e de 100%."}, {"id": 2000001832, "trilha": "tribunais", "materia": "prev", "assunto": "Aposentadorias", "tipo": "pergunta", "frente": "Como funciona a regra de transição do pedágio de 100%?", "verso": "Idade mínima de 60 anos (homem) e 57 (mulher), 35 e 30 anos de contribuição, mais período adicional igual ao que faltava em 13/11/2019.", "explicacao": "EC 103/2019, art. 20. Benefício de 100% da média."}, {"id": 2000001833, "trilha": "tribunais", "materia": "prev", "assunto": "Aposentadorias", "tipo": "pergunta", "frente": "Quais os requisitos da aposentadoria do professor no RGPS (regra permanente)?", "verso": "60 anos (homem) e 57 (mulher), com 25 anos de efetivo exercício nas funções de magistério na educação infantil e no ensino fundamental e médio.", "explicacao": "EC 103/2019, art. 19, § 1º, II."}, {"id": 2000001834, "trilha": "tribunais", "materia": "prev", "assunto": "Aposentadorias", "tipo": "pergunta", "frente": "A aposentadoria especial ainda exige idade mínima?", "verso": "Sim, após a EC 103: 55, 58 ou 60 anos, conforme a atividade exija 15, 20 ou 25 anos de exposição.", "explicacao": "EC 103/2019, art. 19, § 1º, I."}, {"id": 2000001835, "trilha": "tribunais", "materia": "prev", "assunto": "Aposentadorias", "tipo": "pergunta", "frente": "Quem recebe aposentadoria especial pode continuar trabalhando na atividade nociva?", "verso": "Não.", "explicacao": "Lei 8.213/1991, art. 57, § 8º; STF, Tema 709."}, {"id": 2000001836, "trilha": "tribunais", "materia": "prev", "assunto": "Aposentadorias", "tipo": "pergunta", "frente": "Qual o valor da aposentadoria por incapacidade permanente decorrente de acidente do trabalho?", "verso": "100% da média dos salários de contribuição.", "explicacao": "EC 103/2019, art. 26, § 3º, II. Nos demais casos, 60% mais 2% por ano acima de 20 (homem) ou 15 (mulher)."}, {"id": 2000001837, "trilha": "tribunais", "materia": "prev", "assunto": "Aposentadorias", "tipo": "pergunta", "frente": "O aposentado por incapacidade que precisa de assistência permanente de outra pessoa tem direito a quê?", "verso": "Acréscimo de 25% no valor da aposentadoria por incapacidade permanente.", "explicacao": "Lei 8.213/1991, art. 45. Pode ultrapassar o teto."}, {"id": 2000001838, "trilha": "tribunais", "materia": "prev", "assunto": "Benefícios", "tipo": "pergunta", "frente": "Quando começa o auxílio por incapacidade temporária do segurado empregado?", "verso": "A partir do 16º dia de afastamento; os 15 primeiros dias são pagos pela empresa.", "explicacao": "Lei 8.213/1991, art. 60."}, {"id": 2000001839, "trilha": "tribunais", "materia": "prev", "assunto": "Benefícios", "tipo": "pergunta", "frente": "O que é o auxílio-acidente?", "verso": "Indenização paga ao segurado que, após consolidação das lesões de acidente de qualquer natureza, ficar com sequelas que reduzam sua capacidade para o trabalho habitual.", "explicacao": "Lei 8.213/1991, art. 86. Valor de 50% do salário de benefício."}, {"id": 2000001840, "trilha": "tribunais", "materia": "prev", "assunto": "Benefícios", "tipo": "pergunta", "frente": "O auxílio-acidente pode ser acumulado com salário?", "verso": "Sim. Ele é indenizatório e cessa com a aposentadoria.", "explicacao": "Lei 8.213/1991, art. 86, §§ 2º e 3º."}, {"id": 2000001841, "trilha": "tribunais", "materia": "prev", "assunto": "Benefícios", "tipo": "pergunta", "frente": "Quem tem direito ao auxílio-acidente?", "verso": "Empregado, empregado doméstico, trabalhador avulso e segurado especial.", "explicacao": "Lei 8.213/1991, art. 18, § 1º. Contribuinte individual e facultativo não têm."}, {"id": 2000001842, "trilha": "tribunais", "materia": "prev", "assunto": "Benefícios", "tipo": "pergunta", "frente": "Qual a duração do salário-maternidade?", "verso": "120 dias.", "explicacao": "Lei 8.213/1991, art. 71. Empresas do Programa Empresa Cidadã podem prorrogar por 60 dias."}, {"id": 2000001843, "trilha": "tribunais", "materia": "prev", "assunto": "Benefícios", "tipo": "pergunta", "frente": "Quem paga o salário-maternidade da segurada empregada?", "verso": "A empresa, que depois compensa com as contribuições devidas.", "explicacao": "Lei 8.213/1991, art. 72, § 1º."}, {"id": 2000001844, "trilha": "tribunais", "materia": "prev", "assunto": "Benefícios", "tipo": "pergunta", "frente": "O adotante tem direito a salário-maternidade?", "verso": "Sim, por 120 dias, ao segurado ou segurada que adotar ou obtiver guarda judicial para fins de adoção de criança.", "explicacao": "Lei 8.213/1991, art. 71-A."}, {"id": 2000001845, "trilha": "tribunais", "materia": "prev", "assunto": "Benefícios", "tipo": "pergunta", "frente": "Quem tem direito ao salário-família?", "verso": "Segurado de baixa renda (empregado, doméstico, avulso e aposentados nas hipóteses legais), por filho ou equiparado de até 14 anos ou inválido de qualquer idade.", "explicacao": "Lei 8.213/1991, art. 65."}, {"id": 2000001846, "trilha": "tribunais", "materia": "prev", "assunto": "Benefícios", "tipo": "pergunta", "frente": "Quem tem direito ao auxílio-reclusão?", "verso": "Os dependentes do segurado de baixa renda recolhido à prisão em regime fechado.", "explicacao": "Lei 8.213/1991, art. 80 (redação da Lei 13.846/2019)."}, {"id": 2000001847, "trilha": "tribunais", "materia": "prev", "assunto": "Pensão por morte", "tipo": "pergunta", "frente": "Como se calcula a pensão por morte após a EC 103?", "verso": "Cota familiar de 50% do valor da aposentadoria do falecido (ou da que teria por incapacidade), mais 10% por dependente, até 100%.", "explicacao": "EC 103/2019, art. 23."}, {"id": 2000001848, "trilha": "tribunais", "materia": "prev", "assunto": "Pensão por morte", "tipo": "pergunta", "frente": "Qual a duração da pensão por morte do cônjuge com menos de 2 anos de casamento ou menos de 18 contribuições do falecido?", "verso": "4 meses.", "explicacao": "Lei 8.213/1991, art. 77, § 2º, V, b."}, {"id": 2000001849, "trilha": "tribunais", "materia": "prev", "assunto": "Pensão por morte", "tipo": "pergunta", "frente": "A partir de que idade a pensão do cônjuge é vitalícia?", "verso": "Quando o cônjuge tiver 45 anos ou mais na data do óbito (cumpridos 18 contribuições e 2 anos de união).", "explicacao": "Lei 8.213/1991, art. 77, § 2º, V, c, 6, com idades atualizadas por portaria."}, {"id": 2000001850, "trilha": "tribunais", "materia": "prev", "assunto": "Pensão por morte", "tipo": "pergunta", "frente": "Quem comete crime doloso que resulte na morte do segurado perde o direito à pensão?", "verso": "Sim, o condenado por sentença transitada em julgado como autor, coautor ou partícipe de homicídio doloso ou tentativa contra o segurado.", "explicacao": "Lei 8.213/1991, art. 74, § 1º."}, {"id": 2000001851, "trilha": "tribunais", "materia": "prev", "assunto": "Dependentes", "tipo": "pergunta", "frente": "Quais as classes de dependentes do RGPS?", "verso": "1ª: cônjuge, companheiro e filho menor de 21 anos ou inválido ou com deficiência. 2ª: pais. 3ª: irmão menor de 21 anos ou inválido ou com deficiência.", "explicacao": "Lei 8.213/1991, art. 16."}, {"id": 2000001852, "trilha": "tribunais", "materia": "prev", "assunto": "Dependentes", "tipo": "pergunta", "frente": "A existência de dependente de uma classe exclui as seguintes?", "verso": "Sim. Dependentes de classe anterior excluem os das classes seguintes.", "explicacao": "Lei 8.213/1991, art. 16, § 1º."}, {"id": 2000001853, "trilha": "tribunais", "materia": "prev", "assunto": "Dependentes", "tipo": "pergunta", "frente": "A dependência econômica precisa ser provada?", "verso": "Não para a 1ª classe (presumida); deve ser comprovada para pais e irmãos.", "explicacao": "Lei 8.213/1991, art. 16, § 4º."}, {"id": 2000001854, "trilha": "tribunais", "materia": "prev", "assunto": "Dependentes", "tipo": "pergunta", "frente": "O enteado e o menor tutelado são dependentes?", "verso": "Sim, equiparam-se a filho mediante declaração do segurado e comprovação da dependência econômica.", "explicacao": "Lei 8.213/1991, art. 16, § 2º."}, {"id": 2000001855, "trilha": "tribunais", "materia": "prev", "assunto": "Cálculo", "tipo": "pergunta", "frente": "Qual o valor mínimo de benefício que substitui o salário de contribuição?", "verso": "Um salário mínimo.", "explicacao": "CF, art. 201, § 2º."}, {"id": 2000001856, "trilha": "tribunais", "materia": "prev", "assunto": "Cálculo", "tipo": "pergunta", "frente": "Benefícios previdenciários podem ultrapassar o teto do RGPS?", "verso": "Em regra, não. Exceções: salário-maternidade da empregada e o acréscimo de 25% da aposentadoria por incapacidade.", "explicacao": ""}, {"id": 2000001857, "trilha": "tribunais", "materia": "prev", "assunto": "Cálculo", "tipo": "pergunta", "frente": "Qual o fundamento da irredutibilidade do valor dos benefícios previdenciários?", "verso": "A CF assegura o reajustamento dos benefícios para preservar, em caráter permanente, o valor real.", "explicacao": "CF, art. 201, § 4º."}, {"id": 2000001858, "trilha": "tribunais", "materia": "prev", "assunto": "Acumulação", "tipo": "pergunta", "frente": "É possível acumular duas aposentadorias no RGPS?", "verso": "Não.", "explicacao": "Lei 8.213/1991, art. 124, II."}, {"id": 2000001859, "trilha": "tribunais", "materia": "prev", "assunto": "Acumulação", "tipo": "pergunta", "frente": "Como fica a acumulação de pensão por morte com aposentadoria após a EC 103?", "verso": "É permitida, mas o benefício de menor valor sofre redução por faixas (recebe-se integralmente o mais vantajoso e um percentual do outro).", "explicacao": "EC 103/2019, art. 24, § 2º."}, {"id": 2000001860, "trilha": "tribunais", "materia": "prev", "assunto": "Prescrição", "tipo": "pergunta", "frente": "Qual o prazo decadencial para revisar o ato de concessão de benefício?", "verso": "10 anos.", "explicacao": "Lei 8.213/1991, art. 103."}, {"id": 2000001861, "trilha": "tribunais", "materia": "prev", "assunto": "Prescrição", "tipo": "pergunta", "frente": "Qual o prazo de prescrição das prestações vencidas de benefícios?", "verso": "5 anos, contados da data em que deveriam ter sido pagas.", "explicacao": "Lei 8.213/1991, art. 103, parágrafo único."}, {"id": 2000001862, "trilha": "tribunais", "materia": "prev", "assunto": "Assistência social", "tipo": "pergunta", "frente": "Quem tem direito ao BPC (benefício de prestação continuada)?", "verso": "Pessoa com deficiência e idoso com 65 anos ou mais que comprovem não ter meios de prover a própria manutenção nem de tê-la provida pela família.", "explicacao": "CF, art. 203, V; Lei 8.742/1993 (LOAS), art. 20."}, {"id": 2000001863, "trilha": "tribunais", "materia": "prev", "assunto": "Assistência social", "tipo": "pergunta", "frente": "Qual o valor do BPC?", "verso": "Um salário mínimo mensal.", "explicacao": "Não gera pensão por morte nem 13º."}, {"id": 2000001864, "trilha": "tribunais", "materia": "prev", "assunto": "Assistência social", "tipo": "pergunta", "frente": "Qual o critério de renda familiar do BPC?", "verso": "Renda familiar mensal per capita igual ou inferior a 1/4 do salário mínimo, admitidos outros meios de prova da miserabilidade.", "explicacao": "LOAS, art. 20, §§ 3º e 11."}, {"id": 2000001865, "trilha": "tribunais", "materia": "prev", "assunto": "Assistência social", "tipo": "certo_errado", "frente": "Certo ou errado? O BPC exige contribuição prévia à previdência.", "verso": "Errado. A assistência social independe de contribuição.", "explicacao": "CF, art. 203."}, {"id": 2000001866, "trilha": "tribunais", "materia": "prev", "assunto": "Regime próprio", "tipo": "pares", "frente": "RGPS x RPPS.", "verso": "RGPS: regime geral, administrado pelo INSS, para trabalhadores da iniciativa privada e servidores sem regime próprio. RPPS: regime próprio dos servidores titulares de cargo efetivo.", "explicacao": "CF, arts. 40 e 201."}, {"id": 2000001867, "trilha": "tribunais", "materia": "prev", "assunto": "Regime próprio", "tipo": "pergunta", "frente": "Quais os requisitos da aposentadoria voluntária do servidor federal após a EC 103?", "verso": "Homem: 65 anos. Mulher: 62 anos. 25 anos de contribuição, 10 de serviço público e 5 no cargo.", "explicacao": "EC 103/2019, art. 10, § 1º, I."}, {"id": 2000001868, "trilha": "tribunais", "materia": "prev", "assunto": "Regime próprio", "tipo": "pergunta", "frente": "Qual a idade da aposentadoria compulsória do servidor?", "verso": "75 anos.", "explicacao": "CF, art. 40, § 1º, II; LC 152/2015."}, {"id": 2000001869, "trilha": "tribunais", "materia": "prev", "assunto": "Previdência complementar", "tipo": "pergunta", "frente": "A previdência complementar é obrigatória?", "verso": "Não. Tem caráter facultativo, autônomo em relação ao regime geral, baseado em reservas que garantam o benefício.", "explicacao": "CF, art. 202."}, {"id": 2000001870, "trilha": "tribunais", "materia": "prev", "assunto": "Contagem recíproca", "tipo": "pergunta", "frente": "O que é contagem recíproca?", "verso": "Contagem do tempo de contribuição na administração pública e na atividade privada, rural e urbana, com compensação financeira entre os regimes.", "explicacao": "CF, art. 201, § 9º."}, {"id": 2000001871, "trilha": "tribunais", "materia": "trib", "assunto": "Conceito de tributo", "tipo": "pergunta", "frente": "Como o CTN define tributo?", "verso": "Toda prestação pecuniária compulsória, em moeda ou cujo valor nela se possa exprimir, que não constitua sanção de ato ilícito, instituída em lei e cobrada mediante atividade administrativa plenamente vinculada.", "explicacao": "CTN, art. 3º."}, {"id": 2000001872, "trilha": "tribunais", "materia": "trib", "assunto": "Conceito de tributo", "tipo": "certo_errado", "frente": "Certo ou errado? Multa de trânsito é tributo.", "verso": "Errado. Tributo não constitui sanção de ato ilícito; multa é penalidade.", "explicacao": "CTN, art. 3º."}, {"id": 2000001873, "trilha": "tribunais", "materia": "trib", "assunto": "Espécies", "tipo": "pergunta", "frente": "Quais são as espécies tributárias segundo o STF?", "verso": "Impostos, taxas, contribuições de melhoria, empréstimos compulsórios e contribuições especiais (teoria pentapartida).", "explicacao": ""}, {"id": 2000001874, "trilha": "tribunais", "materia": "trib", "assunto": "Espécies", "tipo": "pergunta", "frente": "O que define a natureza jurídica específica do tributo?", "verso": "O fato gerador da obrigação, sendo irrelevantes a denominação e a destinação legal do produto da arrecadação.", "explicacao": "CTN, art. 4º. Não vale para empréstimos compulsórios e contribuições."}, {"id": 2000001875, "trilha": "tribunais", "materia": "trib", "assunto": "Espécies", "tipo": "pares", "frente": "Imposto x taxa.", "verso": "Imposto: tributo não vinculado, independe de atividade estatal específica relativa ao contribuinte. Taxa: vinculado ao exercício do poder de polícia ou a serviço público específico e divisível.", "explicacao": "CTN, arts. 16 e 77."}, {"id": 2000001876, "trilha": "tribunais", "materia": "trib", "assunto": "Espécies", "tipo": "pergunta", "frente": "A taxa pode ter base de cálculo própria de imposto?", "verso": "Não.", "explicacao": "CF, art. 145, § 2º; CTN, art. 77, parágrafo único."}, {"id": 2000001877, "trilha": "tribunais", "materia": "trib", "assunto": "Espécies", "tipo": "pergunta", "frente": "A taxa de coleta de lixo domiciliar é constitucional?", "verso": "Sim, quando se refere exclusivamente à coleta, remoção e tratamento do lixo de imóveis.", "explicacao": "Súmula Vinculante 19."}, {"id": 2000001878, "trilha": "tribunais", "materia": "trib", "assunto": "Espécies", "tipo": "certo_errado", "frente": "Certo ou errado? Serviço de iluminação pública pode ser remunerado por taxa.", "verso": "Errado. Não é específico e divisível; por isso foi criada a contribuição para custeio da iluminação pública (COSIP).", "explicacao": "Súmula Vinculante 41; CF, art. 149-A."}, {"id": 2000001879, "trilha": "tribunais", "materia": "trib", "assunto": "Espécies", "tipo": "pergunta", "frente": "O que é contribuição de melhoria?", "verso": "Tributo cobrado em razão de valorização imobiliária decorrente de obra pública.", "explicacao": "CTN, art. 81. Limite total: o custo da obra; individual: a valorização do imóvel."}, {"id": 2000001880, "trilha": "tribunais", "materia": "trib", "assunto": "Espécies", "tipo": "pergunta", "frente": "Em que casos a União pode instituir empréstimo compulsório?", "verso": "Para despesas extraordinárias de calamidade pública, guerra externa ou sua iminência, e para investimento público de caráter urgente e relevante interesse nacional.", "explicacao": "CF, art. 148. Só por lei complementar."}, {"id": 2000001881, "trilha": "tribunais", "materia": "trib", "assunto": "Espécies", "tipo": "pergunta", "frente": "Quem pode instituir contribuições sociais, de intervenção no domínio econômico e de interesse das categorias profissionais?", "verso": "Exclusivamente a União.", "explicacao": "CF, art. 149. Estados e municípios podem instituir contribuição para o regime próprio de seus servidores."}, {"id": 2000001882, "trilha": "tribunais", "materia": "trib", "assunto": "Competência", "tipo": "pares", "frente": "Competência tributária x capacidade tributária ativa.", "verso": "Competência: poder de instituir tributo por lei; é indelegável. Capacidade ativa: aptidão de arrecadar e fiscalizar; pode ser delegada.", "explicacao": "CTN, art. 7º."}, {"id": 2000001883, "trilha": "tribunais", "materia": "trib", "assunto": "Competência", "tipo": "pergunta", "frente": "O que é competência residual da União?", "verso": "Instituir, por lei complementar, impostos não previstos na CF, desde que não cumulativos e sem fato gerador ou base de cálculo próprios dos já discriminados.", "explicacao": "CF, art. 154, I."}, {"id": 2000001884, "trilha": "tribunais", "materia": "trib", "assunto": "Competência", "tipo": "pergunta", "frente": "O que é imposto extraordinário de guerra?", "verso": "Imposto que a União pode instituir, na iminência ou em caso de guerra externa, compreendidos ou não em sua competência, suprimido gradativamente cessadas as causas.", "explicacao": "CF, art. 154, II."}, {"id": 2000001885, "trilha": "tribunais", "materia": "trib", "assunto": "Competência", "tipo": "pergunta", "frente": "Quais impostos são da competência da União?", "verso": "II, IE, IR, IPI, IOF, ITR e imposto sobre grandes fortunas, além do imposto seletivo da reforma tributária.", "explicacao": "CF, art. 153."}, {"id": 2000001886, "trilha": "tribunais", "materia": "trib", "assunto": "Competência", "tipo": "pergunta", "frente": "Quais impostos são da competência dos estados?", "verso": "ITCMD, ICMS e IPVA.", "explicacao": "CF, art. 155. O ICMS será extinto gradualmente pela reforma tributária, substituído pelo IBS."}, {"id": 2000001887, "trilha": "tribunais", "materia": "trib", "assunto": "Competência", "tipo": "pergunta", "frente": "Quais impostos são da competência dos municípios?", "verso": "IPTU, ITBI e ISS.", "explicacao": "CF, art. 156. O ISS será extinto gradualmente pela reforma tributária, substituído pelo IBS."}, {"id": 2000001888, "trilha": "tribunais", "materia": "trib", "assunto": "Competência", "tipo": "pergunta", "frente": "Quais tributos a reforma tributária (EC 132/2023) criou para substituir PIS, Cofins, ICMS e ISS?", "verso": "A CBS (contribuição federal) e o IBS (imposto de competência compartilhada entre estados e municípios), além do imposto seletivo.", "explicacao": "Transição de 2026 a 2033."}, {"id": 2000001889, "trilha": "tribunais", "materia": "trib", "assunto": "Princípios", "tipo": "pergunta", "frente": "O que diz o princípio da legalidade tributária?", "verso": "É vedado exigir ou aumentar tributo sem lei que o estabeleça.", "explicacao": "CF, art. 150, I."}, {"id": 2000001890, "trilha": "tribunais", "materia": "trib", "assunto": "Princípios", "tipo": "pergunta", "frente": "Quais impostos podem ter alíquotas alteradas por ato do Poder Executivo?", "verso": "II, IE, IPI e IOF, atendidas as condições e os limites da lei.", "explicacao": "CF, art. 153, § 1º. A CIDE-combustíveis também pode ter alíquota reduzida e restabelecida por ato do Executivo (art. 177, § 4º)."}, {"id": 2000001891, "trilha": "tribunais", "materia": "trib", "assunto": "Princípios", "tipo": "pares", "frente": "Anterioridade de exercício x anterioridade nonagesimal.", "verso": "De exercício: o tributo só pode ser cobrado no exercício financeiro seguinte ao da lei que o instituiu ou aumentou. Nonagesimal: só após 90 dias da publicação dessa lei.", "explicacao": "CF, art. 150, III, b e c. Em regra, aplicam-se as duas."}, {"id": 2000001892, "trilha": "tribunais", "materia": "trib", "assunto": "Princípios", "tipo": "pergunta", "frente": "Quais tributos são exceção às duas anterioridades (exercício e noventena)?", "verso": "II, IE, IOF, imposto extraordinário de guerra e empréstimo compulsório para calamidade ou guerra.", "explicacao": "CF, art. 150, § 1º."}, {"id": 2000001893, "trilha": "tribunais", "materia": "trib", "assunto": "Princípios", "tipo": "pergunta", "frente": "Quais tributos respeitam a anterioridade de exercício, mas não a noventena?", "verso": "IR e a fixação da base de cálculo do IPVA e do IPTU.", "explicacao": "CF, art. 150, § 1º."}, {"id": 2000001894, "trilha": "tribunais", "materia": "trib", "assunto": "Princípios", "tipo": "pergunta", "frente": "O IPI respeita qual anterioridade?", "verso": "Só a nonagesimal (90 dias), não a de exercício.", "explicacao": "CF, art. 150, § 1º."}, {"id": 2000001895, "trilha": "tribunais", "materia": "trib", "assunto": "Princípios", "tipo": "pergunta", "frente": "A alteração do prazo de recolhimento de tributo se sujeita à anterioridade?", "verso": "Não.", "explicacao": "Súmula Vinculante 50."}, {"id": 2000001896, "trilha": "tribunais", "materia": "trib", "assunto": "Princípios", "tipo": "pergunta", "frente": "O que diz o princípio da irretroatividade tributária?", "verso": "É vedado cobrar tributos em relação a fatos geradores ocorridos antes do início da vigência da lei que os instituiu ou aumentou.", "explicacao": "CF, art. 150, III, a."}, {"id": 2000001897, "trilha": "tribunais", "materia": "trib", "assunto": "Princípios", "tipo": "pergunta", "frente": "O que é o princípio da vedação ao confisco?", "verso": "É proibido utilizar tributo com efeito de confisco.", "explicacao": "CF, art. 150, IV. O STF também aplica às multas."}, {"id": 2000001898, "trilha": "tribunais", "materia": "trib", "assunto": "Princípios", "tipo": "pergunta", "frente": "O que diz o princípio da capacidade contributiva?", "verso": "Sempre que possível, os impostos terão caráter pessoal e serão graduados segundo a capacidade econômica do contribuinte.", "explicacao": "CF, art. 145, § 1º."}, {"id": 2000001899, "trilha": "tribunais", "materia": "trib", "assunto": "Princípios", "tipo": "pergunta", "frente": "O que proíbe a uniformidade geográfica?", "verso": "Que a União institua tributo que não seja uniforme em todo o território nacional, admitidos incentivos para equilibrar o desenvolvimento entre regiões.", "explicacao": "CF, art. 151, I."}, {"id": 2000001900, "trilha": "tribunais", "materia": "trib", "assunto": "Imunidades", "tipo": "pergunta", "frente": "O que é imunidade recíproca?", "verso": "União, estados, DF e municípios não podem instituir impostos sobre patrimônio, renda ou serviços uns dos outros.", "explicacao": "CF, art. 150, VI, a. Estende-se às autarquias e fundações públicas."}, {"id": 2000001901, "trilha": "tribunais", "materia": "trib", "assunto": "Imunidades", "tipo": "pergunta", "frente": "Quais as imunidades genéricas de impostos?", "verso": "Recíproca; templos de qualquer culto; patrimônio, renda ou serviços de partidos políticos, sindicatos de trabalhadores, entidades de educação e de assistência social sem fins lucrativos; livros, jornais, periódicos e o papel destinado a sua impressão; fonogramas e videofonogramas musicais brasileiros.", "explicacao": "CF, art. 150, VI."}, {"id": 2000001902, "trilha": "tribunais", "materia": "trib", "assunto": "Imunidades", "tipo": "pares", "frente": "Imunidade x isenção.", "verso": "Imunidade: limitação constitucional ao poder de tributar. Isenção: dispensa legal do pagamento do tributo devido (exclusão do crédito).", "explicacao": "Imunidade está na CF; isenção, na lei."}, {"id": 2000001903, "trilha": "tribunais", "materia": "trib", "assunto": "Imunidades", "tipo": "pergunta", "frente": "A imunidade dos livros abrange livros eletrônicos?", "verso": "Sim, inclusive os suportes exclusivamente utilizados para fixá-los (e-readers).", "explicacao": "Súmula Vinculante 57."}, {"id": 2000001904, "trilha": "tribunais", "materia": "trib", "assunto": "Imunidades", "tipo": "pergunta", "frente": "O imóvel de entidade imune alugado a terceiros continua imune ao IPTU?", "verso": "Sim, desde que o valor dos aluguéis seja aplicado nas atividades para as quais a entidade foi constituída.", "explicacao": "Súmula Vinculante 52."}, {"id": 2000001905, "trilha": "tribunais", "materia": "trib", "assunto": "Imunidades", "tipo": "pergunta", "frente": "As imunidades se aplicam às taxas?", "verso": "As do art. 150, VI, só abrangem impostos.", "explicacao": "Há imunidades específicas a taxas, como o direito de petição e certidões (CF, art. 5º, XXXIV)."}, {"id": 2000001906, "trilha": "tribunais", "materia": "trib", "assunto": "Obrigação tributária", "tipo": "pares", "frente": "Obrigação principal x acessória.", "verso": "Principal: pagar tributo ou penalidade pecuniária; extingue-se com o crédito. Acessória: prestações positivas ou negativas no interesse da arrecadação e fiscalização (emitir nota, entregar declaração).", "explicacao": "CTN, art. 113."}, {"id": 2000001907, "trilha": "tribunais", "materia": "trib", "assunto": "Obrigação tributária", "tipo": "pergunta", "frente": "O descumprimento da obrigação acessória gera o quê?", "verso": "Converte-se em obrigação principal relativamente à penalidade pecuniária.", "explicacao": "CTN, art. 113, § 3º."}, {"id": 2000001908, "trilha": "tribunais", "materia": "trib", "assunto": "Obrigação tributária", "tipo": "pares", "frente": "Contribuinte x responsável.", "verso": "Contribuinte: tem relação pessoal e direta com o fato gerador. Responsável: sem ser contribuinte, sua obrigação decorre de disposição expressa de lei.", "explicacao": "CTN, art. 121."}, {"id": 2000001909, "trilha": "tribunais", "materia": "trib", "assunto": "Obrigação tributária", "tipo": "pergunta", "frente": "Convenções particulares sobre quem paga o tributo podem ser opostas ao Fisco?", "verso": "Não, salvo disposição de lei em contrário.", "explicacao": "CTN, art. 123. Ex.: contrato de aluguel que transfere o IPTU ao inquilino."}, {"id": 2000001910, "trilha": "tribunais", "materia": "trib", "assunto": "Obrigação tributária", "tipo": "pergunta", "frente": "A capacidade tributária passiva depende da capacidade civil?", "verso": "Não. Independe da capacidade civil, de estar a pessoa privada de seus bens ou de a pessoa jurídica estar regularmente constituída.", "explicacao": "CTN, art. 126."}, {"id": 2000001911, "trilha": "tribunais", "materia": "trib", "assunto": "Responsabilidade", "tipo": "pergunta", "frente": "Quem adquire fundo de comércio e continua a exploração responde pelos tributos anteriores?", "verso": "Sim: integralmente, se o alienante cessar a atividade; subsidiariamente, se ele prosseguir ou iniciar nova atividade em 6 meses.", "explicacao": "CTN, art. 133."}, {"id": 2000001912, "trilha": "tribunais", "materia": "trib", "assunto": "Responsabilidade", "tipo": "pergunta", "frente": "Quando os sócios-administradores respondem pessoalmente pelos tributos da empresa?", "verso": "Pelos créditos resultantes de atos praticados com excesso de poderes ou infração de lei, contrato social ou estatutos.", "explicacao": "CTN, art. 135. O mero inadimplemento não gera essa responsabilidade (Súmula 430 do STJ)."}, {"id": 2000001913, "trilha": "tribunais", "materia": "trib", "assunto": "Responsabilidade", "tipo": "pergunta", "frente": "A dissolução irregular da empresa permite redirecionar a execução fiscal ao sócio-gerente?", "verso": "Sim. Presume-se dissolvida irregularmente a empresa que deixa de funcionar no domicílio fiscal sem comunicar aos órgãos competentes.", "explicacao": "Súmula 435 do STJ."}, {"id": 2000001914, "trilha": "tribunais", "materia": "trib", "assunto": "Responsabilidade", "tipo": "pergunta", "frente": "A denúncia espontânea exclui a multa?", "verso": "Sim, se o contribuinte confessar e pagar o tributo com juros antes de qualquer procedimento fiscal.", "explicacao": "CTN, art. 138. Não se aplica a tributo declarado e pago com atraso (Súmula 360 do STJ)."}, {"id": 2000001915, "trilha": "tribunais", "materia": "trib", "assunto": "Crédito tributário", "tipo": "pares", "frente": "Lançamento de ofício x por declaração x por homologação.", "verso": "De ofício: a autoridade faz tudo (IPTU, IPVA). Por declaração: o contribuinte informa e o fisco calcula (ITBI e ITCMD, em geral). Por homologação: o contribuinte apura e paga e o fisco confere (ICMS, IR, IPI).", "explicacao": "CTN, arts. 147 a 150."}, {"id": 2000001916, "trilha": "tribunais", "materia": "trib", "assunto": "Crédito tributário", "tipo": "pergunta", "frente": "Em quanto tempo ocorre a homologação tácita do lançamento?", "verso": "5 anos a contar do fato gerador, se a lei não fixar outro prazo, salvo dolo, fraude ou simulação.", "explicacao": "CTN, art. 150, § 4º."}, {"id": 2000001917, "trilha": "tribunais", "materia": "trib", "assunto": "Crédito tributário", "tipo": "pergunta", "frente": "A declaração do contribuinte (DCTF, GIA) constitui o crédito tributário?", "verso": "Sim, dispensando qualquer outra providência do fisco.", "explicacao": "Súmula 436 do STJ."}, {"id": 2000001918, "trilha": "tribunais", "materia": "trib", "assunto": "Suspensão", "tipo": "pergunta", "frente": "Quais são as hipóteses de suspensão da exigibilidade do crédito tributário?", "verso": "Moratória, depósito do montante integral, reclamações e recursos administrativos, liminar em mandado de segurança, liminar ou tutela antecipada em outras ações e parcelamento.", "explicacao": "CTN, art. 151. Mnemônico: MO-DE-RE-CO-LI-PA."}, {"id": 2000001919, "trilha": "tribunais", "materia": "trib", "assunto": "Suspensão", "tipo": "pergunta", "frente": "Para suspender a exigibilidade, o depósito deve ser como?", "verso": "Do montante integral e em dinheiro.", "explicacao": "Súmula 112 do STJ."}, {"id": 2000001920, "trilha": "tribunais", "materia": "trib", "assunto": "Extinção", "tipo": "pergunta", "frente": "Cite modalidades de extinção do crédito tributário.", "verso": "Pagamento, compensação, transação, remissão, prescrição e decadência, conversão de depósito em renda, pagamento antecipado com homologação, consignação, decisão administrativa irreformável, decisão judicial passada em julgado e dação em pagamento de imóveis.", "explicacao": "CTN, art. 156."}, {"id": 2000001921, "trilha": "tribunais", "materia": "trib", "assunto": "Extinção", "tipo": "pares", "frente": "Remissão x anistia.", "verso": "Remissão: perdão do crédito tributário (tributo e multa), extinguindo-o. Anistia: perdão só das infrações (multas), excluindo o crédito.", "explicacao": "CTN, arts. 156, IV, e 180."}, {"id": 2000001922, "trilha": "tribunais", "materia": "trib", "assunto": "Extinção", "tipo": "pares", "frente": "Decadência x prescrição tributária.", "verso": "Decadência: prazo de 5 anos para o fisco constituir o crédito (lançar). Prescrição: prazo de 5 anos para cobrar o crédito já constituído.", "explicacao": "CTN, arts. 173 e 174."}, {"id": 2000001923, "trilha": "tribunais", "materia": "trib", "assunto": "Extinção", "tipo": "pergunta", "frente": "Quando se inicia o prazo decadencial na regra geral do art. 173, I?", "verso": "No primeiro dia do exercício seguinte àquele em que o lançamento poderia ter sido efetuado.", "explicacao": "CTN, art. 173, I."}, {"id": 2000001924, "trilha": "tribunais", "materia": "trib", "assunto": "Extinção", "tipo": "pergunta", "frente": "O que interrompe a prescrição tributária?", "verso": "Despacho do juiz que ordena a citação na execução fiscal, protesto judicial, ato judicial que constitua em mora o devedor e ato inequívoco de reconhecimento do débito pelo devedor.", "explicacao": "CTN, art. 174, parágrafo único."}, {"id": 2000001925, "trilha": "tribunais", "materia": "trib", "assunto": "Exclusão", "tipo": "pergunta", "frente": "Quais as hipóteses de exclusão do crédito tributário?", "verso": "Isenção e anistia.", "explicacao": "CTN, art. 175."}, {"id": 2000001926, "trilha": "tribunais", "materia": "trib", "assunto": "Exclusão", "tipo": "pergunta", "frente": "A isenção concedida por prazo certo e em função de condições pode ser revogada a qualquer tempo?", "verso": "Não, ela não pode ser livremente suprimida, respeitado o direito adquirido de quem cumpriu as condições.", "explicacao": "CTN, art. 178; Súmula 544 do STF."}, {"id": 2000001927, "trilha": "tribunais", "materia": "trib", "assunto": "Garantias", "tipo": "pergunta", "frente": "Qual a preferência do crédito tributário na falência?", "verso": "Fica atrás dos créditos extraconcursais, das importâncias passíveis de restituição, dos créditos trabalhistas (limitados a 150 salários mínimos por credor) e dos créditos com garantia real até o valor do bem gravado.", "explicacao": "CTN, art. 186; Lei 11.101/2005, art. 83."}, {"id": 2000001928, "trilha": "tribunais", "materia": "trib", "assunto": "Garantias", "tipo": "pergunta", "frente": "Quando se presume fraudulenta a alienação de bens pelo devedor tributário?", "verso": "Quando feita após a inscrição do crédito em dívida ativa, sem reserva de bens suficientes para o pagamento.", "explicacao": "CTN, art. 185."}, {"id": 2000001929, "trilha": "tribunais", "materia": "trib", "assunto": "Administração tributária", "tipo": "pergunta", "frente": "A certidão positiva com efeitos de negativa é emitida quando?", "verso": "Quando existirem créditos não vencidos, em curso de cobrança executiva com penhora efetivada, ou com exigibilidade suspensa.", "explicacao": "CTN, art. 206."}, {"id": 2000001930, "trilha": "tribunais", "materia": "trib", "assunto": "Administração tributária", "tipo": "pergunta", "frente": "O que é a dívida ativa tributária?", "verso": "O crédito tributário regularmente inscrito na repartição competente, após esgotado o prazo para pagamento.", "explicacao": "CTN, art. 201. A inscrição goza de presunção relativa de certeza e liquidez."}, {"id": 2000001931, "trilha": "tribunais", "materia": "trib", "assunto": "Impostos", "tipo": "pergunta", "frente": "Qual o fato gerador do IPVA?", "verso": "A propriedade de veículo automotor.", "explicacao": "Após a EC 132, alcança também veículos aquáticos e aéreos, com exceções."}, {"id": 2000001932, "trilha": "tribunais", "materia": "trib", "assunto": "Impostos", "tipo": "pergunta", "frente": "Qual o fato gerador do ITBI e quando ele é devido?", "verso": "A transmissão onerosa inter vivos de bens imóveis; é devido com o registro da transferência no cartório.", "explicacao": "STF, Tema 1.124."}, {"id": 2000001933, "trilha": "tribunais", "materia": "trib", "assunto": "Impostos", "tipo": "pergunta", "frente": "O IPTU pode ser progressivo?", "verso": "Sim, em razão do valor do imóvel, ter alíquotas diferentes conforme localização e uso, e ser progressivo no tempo para imóvel não edificado ou subutilizado.", "explicacao": "CF, arts. 156, § 1º, e 182, § 4º, II."}, {"id": 2000001934, "trilha": "tribunais", "materia": "trib", "assunto": "Impostos", "tipo": "pergunta", "frente": "Qual o princípio que o IPI e o ICMS devem observar quanto à cumulatividade?", "verso": "Não cumulatividade: compensa-se o devido em cada operação com o cobrado nas anteriores.", "explicacao": "CF, arts. 153, § 3º, II, e 155, § 2º, I."}, {"id": 2000001935, "trilha": "tribunais", "materia": "trib", "assunto": "Impostos", "tipo": "pares", "frente": "IPI: seletividade obrigatória x ICMS: seletividade facultativa.", "verso": "O IPI será seletivo em função da essencialidade do produto. O ICMS poderá ser seletivo.", "explicacao": "CF, arts. 153, § 3º, I, e 155, § 2º, III."}, {"id": 2000001936, "trilha": "tribunais", "materia": "trib", "assunto": "Impostos", "tipo": "pergunta", "frente": "Quais os princípios do imposto de renda?", "verso": "Generalidade, universalidade e progressividade.", "explicacao": "CF, art. 153, § 2º, I."}, {"id": 2000001937, "trilha": "tribunais", "materia": "trib", "assunto": "Impostos", "tipo": "pergunta", "frente": "O ITR incide sobre pequenas glebas rurais?", "verso": "Não, quando exploradas pelo proprietário que não possua outro imóvel.", "explicacao": "CF, art. 153, § 4º, II. Pode ser fiscalizado e cobrado pelos municípios que optarem."}, {"id": 2000001938, "trilha": "tribunais", "materia": "trib", "assunto": "Repartição de receitas", "tipo": "pergunta", "frente": "Quanto do IPVA fica com o município?", "verso": "50% do IPVA dos veículos licenciados em seu território.", "explicacao": "CF, art. 158, III."}, {"id": 2000001939, "trilha": "tribunais", "materia": "trib", "assunto": "Execução fiscal", "tipo": "pergunta", "frente": "Qual o prazo para opor embargos à execução fiscal e o que exige?", "verso": "30 dias, contados do depósito, da juntada da prova da fiança bancária ou do seguro garantia, ou da intimação da penhora; exige garantia do juízo.", "explicacao": "Lei 6.830/1980, art. 16."}, {"id": 2000001940, "trilha": "tribunais", "materia": "trib", "assunto": "Execução fiscal", "tipo": "pergunta", "frente": "Quando ocorre a prescrição intercorrente na execução fiscal?", "verso": "Após 1 ano de suspensão por não localização do devedor ou de bens, inicia-se o prazo de 5 anos; ao fim, o juiz, ouvida a Fazenda, decreta a prescrição.", "explicacao": "Lei 6.830/1980, art. 40; STJ, Tema 566."}, {"id": 2000001941, "trilha": "tribunais", "materia": "gest", "assunto": "Modelos de administração", "tipo": "pares", "frente": "Administração patrimonialista x burocrática x gerencial.", "verso": "Patrimonialista: confusão entre público e privado, nepotismo, corrupção. Burocrática: impessoalidade, hierarquia, formalismo e controle de procedimentos (a priori). Gerencial: foco em resultados, eficiência e cidadão-cliente (controle a posteriori).", "explicacao": "Reforma de 1995 (Bresser-Pereira) introduziu o modelo gerencial."}, {"id": 2000001942, "trilha": "tribunais", "materia": "gest", "assunto": "Modelos de administração", "tipo": "pergunta", "frente": "Quais as características da burocracia segundo Max Weber?", "verso": "Caráter legal das normas, formalidade, impessoalidade, hierarquia, rotinas padronizadas, competência técnica e meritocracia, especialização e profissionalização.", "explicacao": "Dominação racional-legal."}, {"id": 2000001943, "trilha": "tribunais", "materia": "gest", "assunto": "Modelos de administração", "tipo": "pergunta", "frente": "O que são as disfunções da burocracia (Merton)?", "verso": "Efeitos indesejados: apego excessivo às regras, excesso de papelada, resistência a mudanças, despersonalização, superconformidade e dificuldade no atendimento ao público.", "explicacao": ""}, {"id": 2000001944, "trilha": "tribunais", "materia": "gest", "assunto": "Modelos de administração", "tipo": "pergunta", "frente": "Qual reforma introduziu a burocracia no Brasil?", "verso": "A Reforma Burocrática de 1936, no governo Vargas, com a criação do DASP (Departamento Administrativo do Serviço Público, 1938).", "explicacao": "Concursos públicos e carreiras."}, {"id": 2000001945, "trilha": "tribunais", "materia": "gest", "assunto": "Modelos de administração", "tipo": "pergunta", "frente": "O que foi o Decreto-Lei 200/1967?", "verso": "Reforma que descentralizou a administração, ampliando a administração indireta (autarquias, fundações, empresas públicas e sociedades de economia mista).", "explicacao": "Considerado um primeiro ensaio de administração gerencial."}, {"id": 2000001946, "trilha": "tribunais", "materia": "gest", "assunto": "Modelos de administração", "tipo": "pergunta", "frente": "O que foi o PDRAE de 1995?", "verso": "Plano Diretor da Reforma do Aparelho do Estado, de Bresser-Pereira, que propôs o modelo gerencial, as agências executivas e as organizações sociais.", "explicacao": "Dividiu o Estado em núcleo estratégico, atividades exclusivas, serviços não exclusivos e produção para o mercado."}, {"id": 2000001947, "trilha": "tribunais", "materia": "gest", "assunto": "Modelos de administração", "tipo": "pergunta", "frente": "O que é a Nova Gestão Pública (New Public Management)?", "verso": "Movimento que levou ao setor público ferramentas da gestão privada: foco em resultados, contratos de gestão, descentralização e avaliação de desempenho.", "explicacao": "Origem no Reino Unido (Thatcher) e na Nova Zelândia."}, {"id": 2000001948, "trilha": "tribunais", "materia": "gest", "assunto": "Modelos de administração", "tipo": "pergunta", "frente": "O que é governança pública?", "verso": "Mecanismos de liderança, estratégia e controle para avaliar, direcionar e monitorar a gestão, com vistas à prestação de serviços de interesse da sociedade.", "explicacao": "Decreto 9.203/2017."}, {"id": 2000001949, "trilha": "tribunais", "materia": "gest", "assunto": "Modelos de administração", "tipo": "pergunta", "frente": "Quais os princípios da governança pública no Decreto 9.203/2017?", "verso": "Capacidade de resposta, integridade, confiabilidade, melhoria regulatória, prestação de contas e responsabilidade, e transparência.", "explicacao": "Decreto 9.203/2017, art. 3º."}, {"id": 2000001950, "trilha": "tribunais", "materia": "gest", "assunto": "Modelos de administração", "tipo": "pergunta", "frente": "O que é accountability?", "verso": "A obrigação de prestar contas e de ser responsabilizado pelos atos e resultados da gestão.", "explicacao": "Vertical (eleitor) e horizontal (entre órgãos e Poderes)."}, {"id": 2000001951, "trilha": "tribunais", "materia": "gest", "assunto": "Funções administrativas", "tipo": "pergunta", "frente": "Quais são as funções administrativas (processo administrativo)?", "verso": "Planejar, organizar, dirigir e controlar (PODC).", "explicacao": "Fayol propôs prever, organizar, comandar, coordenar e controlar."}, {"id": 2000001952, "trilha": "tribunais", "materia": "gest", "assunto": "Planejamento", "tipo": "pares", "frente": "Planejamento estratégico x tático x operacional.", "verso": "Estratégico: longo prazo, toda a organização, alta direção. Tático: médio prazo, por departamento, gerência intermediária. Operacional: curto prazo, tarefas, nível operacional.", "explicacao": ""}, {"id": 2000001953, "trilha": "tribunais", "materia": "gest", "assunto": "Planejamento", "tipo": "pergunta", "frente": "O que é a análise SWOT?", "verso": "Ferramenta que cruza forças e fraquezas (ambiente interno) com oportunidades e ameaças (ambiente externo).", "explicacao": "Em português: FOFA."}, {"id": 2000001954, "trilha": "tribunais", "materia": "gest", "assunto": "Planejamento", "tipo": "pares", "frente": "Missão x visão x valores.", "verso": "Missão: razão de ser da organização (o que faz e para quem). Visão: onde quer chegar no futuro. Valores: princípios que orientam o comportamento.", "explicacao": ""}, {"id": 2000001955, "trilha": "tribunais", "materia": "gest", "assunto": "Planejamento", "tipo": "pergunta", "frente": "O que é o Balanced Scorecard?", "verso": "Ferramenta de gestão estratégica (Kaplan e Norton) que traduz a estratégia em objetivos e indicadores em quatro perspectivas.", "explicacao": "Financeira, clientes, processos internos e aprendizado e crescimento."}, {"id": 2000001956, "trilha": "tribunais", "materia": "gest", "assunto": "Planejamento", "tipo": "pergunta", "frente": "No setor público, como costuma ser adaptado o Balanced Scorecard?", "verso": "A perspectiva do cidadão/sociedade fica no topo, no lugar da financeira.", "explicacao": ""}, {"id": 2000001957, "trilha": "tribunais", "materia": "gest", "assunto": "Planejamento", "tipo": "pergunta", "frente": "O que são objetivos SMART?", "verso": "Específicos, mensuráveis, atingíveis, relevantes e temporais (com prazo).", "explicacao": ""}, {"id": 2000001958, "trilha": "tribunais", "materia": "gest", "assunto": "Organização", "tipo": "pares", "frente": "Departamentalização funcional x por produto x geográfica x por processos.", "verso": "Funcional: por especialidade (finanças, RH). Por produto ou serviço: por linha de produto. Geográfica: por região. Por processos: pelas etapas do fluxo de trabalho.", "explicacao": "Há também por clientes, por projetos e matricial."}, {"id": 2000001959, "trilha": "tribunais", "materia": "gest", "assunto": "Organização", "tipo": "pergunta", "frente": "O que é a estrutura matricial?", "verso": "Combina departamentalização funcional e por projetos; o empregado responde a dois chefes.", "explicacao": "Dupla subordinação."}, {"id": 2000001960, "trilha": "tribunais", "materia": "gest", "assunto": "Organização", "tipo": "pares", "frente": "Centralização x descentralização.", "verso": "Centralização: decisões concentradas no topo, maior controle e uniformidade. Descentralização: decisões delegadas aos níveis inferiores, mais agilidade e proximidade do problema.", "explicacao": ""}, {"id": 2000001961, "trilha": "tribunais", "materia": "gest", "assunto": "Organização", "tipo": "pergunta", "frente": "O que é amplitude de controle?", "verso": "O número de subordinados que um gestor supervisiona diretamente.", "explicacao": "Amplitude grande gera estrutura achatada (horizontal)."}, {"id": 2000001962, "trilha": "tribunais", "materia": "gest", "assunto": "Organização", "tipo": "pares", "frente": "Delegação x descentralização.", "verso": "Delegação: transferência de autoridade a uma pessoa, para tarefas específicas. Descentralização: distribuição sistemática de poder decisório por toda a estrutura.", "explicacao": ""}, {"id": 2000001963, "trilha": "tribunais", "materia": "gest", "assunto": "Direção", "tipo": "pares", "frente": "Liderança autocrática x democrática x liberal (laissez-faire).", "verso": "Autocrática: o líder decide sozinho. Democrática: decisões com participação do grupo. Liberal: o grupo decide com pouca intervenção do líder.", "explicacao": "Estudo de White e Lippitt."}, {"id": 2000001964, "trilha": "tribunais", "materia": "gest", "assunto": "Direção", "tipo": "pergunta", "frente": "O que diz a liderança situacional (Hersey e Blanchard)?", "verso": "O estilo do líder (determinar, persuadir, compartilhar, delegar) deve variar conforme a maturidade dos liderados.", "explicacao": ""}, {"id": 2000001965, "trilha": "tribunais", "materia": "gest", "assunto": "Direção", "tipo": "pares", "frente": "Liderança transacional x transformacional.", "verso": "Transacional: troca de recompensas por desempenho, foco em metas e controle. Transformacional: inspira, motiva e desenvolve os liderados para além dos interesses imediatos.", "explicacao": ""}, {"id": 2000001966, "trilha": "tribunais", "materia": "gest", "assunto": "Motivação", "tipo": "pergunta", "frente": "Qual a ordem da pirâmide de Maslow, da base ao topo?", "verso": "Fisiológicas, segurança, sociais, estima e autorrealização.", "explicacao": "Necessidades de nível inferior precisam ser satisfeitas antes."}, {"id": 2000001967, "trilha": "tribunais", "materia": "gest", "assunto": "Motivação", "tipo": "pares", "frente": "Fatores higiênicos x motivacionais (Herzberg).", "verso": "Higiênicos: extrínsecos (salário, condições de trabalho, supervisão); evitam insatisfação, mas não motivam. Motivacionais: intrínsecos (reconhecimento, responsabilidade, crescimento); geram satisfação.", "explicacao": "Teoria dos dois fatores."}, {"id": 2000001968, "trilha": "tribunais", "materia": "gest", "assunto": "Motivação", "tipo": "pares", "frente": "Teoria X x teoria Y (McGregor).", "verso": "X: as pessoas não gostam de trabalhar e precisam ser controladas. Y: as pessoas gostam de trabalhar, buscam responsabilidade e podem se autodirigir.", "explicacao": ""}, {"id": 2000001969, "trilha": "tribunais", "materia": "gest", "assunto": "Motivação", "tipo": "pergunta", "frente": "O que diz a teoria da expectância (Vroom)?", "verso": "A motivação depende da expectativa de que o esforço gera desempenho, de que o desempenho gera recompensa (instrumentalidade) e do valor dado à recompensa (valência).", "explicacao": ""}, {"id": 2000001970, "trilha": "tribunais", "materia": "gest", "assunto": "Controle", "tipo": "pares", "frente": "Eficiência x eficácia x efetividade.", "verso": "Eficiência: fazer bem, com menos recursos (meios). Eficácia: atingir as metas e objetivos (resultados). Efetividade: impacto real gerado na sociedade.", "explicacao": "Questão clássica."}, {"id": 2000001971, "trilha": "tribunais", "materia": "gest", "assunto": "Controle", "tipo": "pares", "frente": "Indicadores de insumo x processo x produto x resultado.", "verso": "Insumo: recursos usados. Processo: como se trabalha. Produto (output): bens e serviços entregues. Resultado/impacto (outcome): efeitos na sociedade.", "explicacao": ""}, {"id": 2000001972, "trilha": "tribunais", "materia": "gest", "assunto": "Qualidade", "tipo": "pergunta", "frente": "O que é o ciclo PDCA?", "verso": "Método de melhoria contínua: Plan (planejar), Do (executar), Check (verificar) e Act (agir corretivamente).", "explicacao": "Ciclo de Deming (ou de Shewhart)."}, {"id": 2000001973, "trilha": "tribunais", "materia": "gest", "assunto": "Qualidade", "tipo": "pergunta", "frente": "Para que serve o diagrama de Ishikawa?", "verso": "Identificar as causas de um problema, agrupadas em categorias (método, máquina, material, mão de obra, meio ambiente e medida).", "explicacao": "Também chamado de espinha de peixe ou de causa e efeito."}, {"id": 2000001974, "trilha": "tribunais", "materia": "gest", "assunto": "Qualidade", "tipo": "pergunta", "frente": "O que diz o princípio de Pareto?", "verso": "Cerca de 80% dos efeitos vêm de 20% das causas; foca-se nas causas mais relevantes.", "explicacao": "Gráfico de Pareto."}, {"id": 2000001975, "trilha": "tribunais", "materia": "gest", "assunto": "Qualidade", "tipo": "pergunta", "frente": "O que é o 5W2H?", "verso": "Plano de ação que responde: o quê, por quê, onde, quando, quem, como e quanto custa.", "explicacao": "What, Why, Where, When, Who, How, How much."}, {"id": 2000001976, "trilha": "tribunais", "materia": "gest", "assunto": "Qualidade", "tipo": "pergunta", "frente": "O que é benchmarking?", "verso": "Comparar práticas e resultados com os de organizações referência para identificar e adaptar as melhores práticas.", "explicacao": ""}, {"id": 2000001977, "trilha": "tribunais", "materia": "gest", "assunto": "Qualidade", "tipo": "pergunta", "frente": "O que é o programa 5S?", "verso": "Programa de organização do ambiente de trabalho: utilização (seiri), ordenação (seiton), limpeza (seiso), saúde/padronização (seiketsu) e autodisciplina (shitsuke).", "explicacao": "Origem japonesa."}, {"id": 2000001978, "trilha": "tribunais", "materia": "gest", "assunto": "Processos", "tipo": "pergunta", "frente": "O que é gestão por processos?", "verso": "Organizar o trabalho pelos fluxos que entregam valor ao cliente, de ponta a ponta, atravessando os departamentos.", "explicacao": "Notação comum: BPMN."}, {"id": 2000001979, "trilha": "tribunais", "materia": "gest", "assunto": "Processos", "tipo": "pares", "frente": "Melhoria contínua (kaizen) x reengenharia.", "verso": "Kaizen: mudanças pequenas e graduais. Reengenharia: redesenho radical dos processos para ganhos drásticos.", "explicacao": ""}, {"id": 2000001980, "trilha": "tribunais", "materia": "gest", "assunto": "Projetos", "tipo": "pergunta", "frente": "Quais as características de um projeto?", "verso": "Esforço temporário, com início e fim definidos, para criar um produto, serviço ou resultado único.", "explicacao": "PMBOK."}, {"id": 2000001981, "trilha": "tribunais", "materia": "gest", "assunto": "Projetos", "tipo": "pergunta", "frente": "O que é a tripla restrição em projetos?", "verso": "Escopo, prazo e custo, que se influenciam mutuamente (e afetam a qualidade).", "explicacao": ""}, {"id": 2000001982, "trilha": "tribunais", "materia": "gest", "assunto": "Projetos", "tipo": "pergunta", "frente": "O que é caminho crítico?", "verso": "A sequência de atividades mais longa do projeto, sem folga; qualquer atraso nela atrasa o projeto inteiro.", "explicacao": ""}, {"id": 2000001983, "trilha": "tribunais", "materia": "gest", "assunto": "Gestão de pessoas", "tipo": "pergunta", "frente": "O que é gestão por competências?", "verso": "Gestão que identifica as competências (conhecimentos, habilidades e atitudes — CHA) necessárias e desenvolve os servidores para reduzir lacunas.", "explicacao": "Decreto 9.991/2019 (PNDP) na administração federal."}, {"id": 2000001984, "trilha": "tribunais", "materia": "gest", "assunto": "Gestão de pessoas", "tipo": "pares", "frente": "Recrutamento interno x externo.", "verso": "Interno: preenche a vaga com quem já está na organização (motiva, é mais rápido e barato). Externo: busca candidatos de fora (traz novas ideias, mas é mais caro e lento).", "explicacao": ""}, {"id": 2000001985, "trilha": "tribunais", "materia": "gest", "assunto": "Gestão de pessoas", "tipo": "pares", "frente": "Treinamento x desenvolvimento.", "verso": "Treinamento: foco no cargo atual, curto prazo. Desenvolvimento: foco em cargos futuros e crescimento da pessoa, longo prazo.", "explicacao": ""}, {"id": 2000001986, "trilha": "tribunais", "materia": "gest", "assunto": "Gestão de pessoas", "tipo": "pergunta", "frente": "O que é avaliação de desempenho 360 graus?", "verso": "Avaliação feita por todos que interagem com o avaliado: chefe, colegas, subordinados, clientes e ele mesmo.", "explicacao": ""}, {"id": 2000001987, "trilha": "tribunais", "materia": "gest", "assunto": "Gestão de pessoas", "tipo": "pergunta", "frente": "O que é o efeito halo na avaliação de desempenho?", "verso": "Quando uma característica marcante do avaliado contamina a avaliação de todos os outros aspectos.", "explicacao": "Outros vieses: tendência central, leniência, recência."}, {"id": 2000001988, "trilha": "tribunais", "materia": "gest", "assunto": "Gestão de pessoas", "tipo": "pergunta", "frente": "O que é cultura organizacional?", "verso": "Conjunto de valores, crenças, normas, rituais e pressupostos compartilhados pelos membros da organização.", "explicacao": "Schein: artefatos, valores declarados e pressupostos básicos."}, {"id": 2000001989, "trilha": "tribunais", "materia": "gest", "assunto": "Gestão de pessoas", "tipo": "pergunta", "frente": "O que é clima organizacional?", "verso": "A percepção dos membros sobre o ambiente de trabalho, que afeta sua motivação e comportamento.", "explicacao": "É mais mutável que a cultura."}, {"id": 2000001990, "trilha": "tribunais", "materia": "gest", "assunto": "Comunicação", "tipo": "pares", "frente": "Comunicação formal x informal.", "verso": "Formal: pelos canais oficiais da organização (memorandos, ofícios). Informal: pelas relações pessoais (“rádio peão”).", "explicacao": ""}, {"id": 2000001991, "trilha": "tribunais", "materia": "gest", "assunto": "Conflitos", "tipo": "pergunta", "frente": "Quais os estilos de gestão de conflitos (Thomas-Kilmann)?", "verso": "Competição, colaboração, compromisso (acomodação mútua), evitação e acomodação.", "explicacao": "Colaboração busca solução ganha-ganha."}, {"id": 2000001992, "trilha": "tribunais", "materia": "gest", "assunto": "Atendimento", "tipo": "pergunta", "frente": "Quais as características de um bom atendimento ao público?", "verso": "Cortesia, presteza, clareza, atenção, empatia, objetividade e respeito às prioridades legais.", "explicacao": ""}, {"id": 2000001993, "trilha": "tribunais", "materia": "gest", "assunto": "Atendimento", "tipo": "pergunta", "frente": "Qual lei trata dos direitos dos usuários dos serviços públicos?", "verso": "A Lei 13.460/2017 (Código de Defesa do Usuário do Serviço Público).", "explicacao": "Prevê as ouvidorias e a Carta de Serviços ao Usuário."}, {"id": 2000001994, "trilha": "tribunais", "materia": "gest", "assunto": "Atendimento", "tipo": "pergunta", "frente": "O que é a Carta de Serviços ao Usuário?", "verso": "Documento que informa os serviços prestados pelo órgão, os requisitos, prazos, formas de acesso e compromissos de qualidade.", "explicacao": "Lei 13.460/2017, art. 7º."}, {"id": 2000001995, "trilha": "tribunais", "materia": "gest", "assunto": "Atendimento", "tipo": "pergunta", "frente": "Quem tem atendimento prioritário pela Lei 10.048/2000?", "verso": "Pessoas com deficiência, idosos com 60 anos ou mais, gestantes, lactantes, pessoas com crianças de colo, obesos, pessoas com mobilidade reduzida, pessoas com transtorno do espectro autista e doadores de sangue.", "explicacao": "Lei 10.048/2000, art. 1º."}, {"id": 2000001996, "trilha": "tribunais", "materia": "gest", "assunto": "Transparência", "tipo": "pares", "frente": "Transparência ativa x passiva.", "verso": "Ativa: o órgão divulga as informações por iniciativa própria (portais). Passiva: fornece as informações quando solicitadas.", "explicacao": "Lei 12.527/2011 (LAI)."}, {"id": 2000001997, "trilha": "tribunais", "materia": "gest", "assunto": "Transparência", "tipo": "pergunta", "frente": "Qual o prazo de resposta a um pedido de acesso à informação na LAI?", "verso": "Até 20 dias, prorrogáveis por mais 10, mediante justificativa.", "explicacao": "Lei 12.527/2011, art. 11."}, {"id": 2000001998, "trilha": "tribunais", "materia": "gest", "assunto": "Transparência", "tipo": "pergunta", "frente": "É preciso justificar o motivo de um pedido de acesso à informação?", "verso": "Não. São vedadas exigências relativas aos motivos determinantes da solicitação.", "explicacao": "Lei 12.527/2011, art. 10, § 3º."}, {"id": 2000001999, "trilha": "tribunais", "materia": "gest", "assunto": "Orçamento", "tipo": "pergunta", "frente": "Quais os instrumentos de planejamento orçamentário da CF?", "verso": "Plano Plurianual (PPA), Lei de Diretrizes Orçamentárias (LDO) e Lei Orçamentária Anual (LOA).", "explicacao": "CF, art. 165."}, {"id": 2000002000, "trilha": "tribunais", "materia": "gest", "assunto": "Orçamento", "tipo": "pergunta", "frente": "Qual a vigência do PPA?", "verso": "4 anos: começa no segundo ano do mandato e termina no primeiro ano do mandato seguinte.", "explicacao": ""}]$c$::jsonb) as x(id integer, trilha text, materia text, assunto text, tipo text, frente text, verso text, explicacao text)
on conflict (id) do update set trilha = excluded.trilha, materia = excluded.materia, assunto = excluded.assunto, tipo = excluded.tipo,
  frente = excluded.frente, verso = excluded.verso, explicacao = excluded.explicacao, ativa = true, atualizado_em = now();

select trilha, count(*) as cartoes, public.cartoes_versao() as versao from public.cartoes where ativa group by trilha;
